// ==UserScript==
// @name         Crusoe L&N Dashboard — Live (DRAFT v2)
// @namespace    crusoe-lndash
// @version      0.5.0-draft
// @description  Draggable launcher that pulls live PAT/NAPLAN/TJ data from Compass, discovering the whole school's classes the same way Reports Check does, and renders it inside the existing dashboard layout unmodified.
// @match        https://crusoecollege-vic.compass.education/*
// @grant        none
// ==/UserScript==

// ============================================================================
// BUILD: this is the SOURCE file. Do not install it directly. Run
//   scripts/build-userscript.sh
// which inlines the data-free index.html and writes dist/lndash-live.user.js.
// That built file is what staff use. It is published to the public
// compassaddons repo by scripts/publish-to-compassaddons.sh, and the Compass
// Tools menu loads it from there, so staff always get the latest build.
// The built file is code plus the data-free template only.
// ============================================================================
// STATUS: IN TESTING. Shown in the Compass Tools menu as "In testing". It
// displays whatever Compass returns; the TODOs below mark parts not yet
// confirmed against real data.
//
// CHANGE FROM v1: whole-school class discovery no longer depends on the
// unverified GetThinClasses endpoint. Instead it walks Compass the same way
// Reports Check does — GetReportsStaff (every staff member reporting in a
// cycle) -> GetOpenCycleActivitiesByUserId (every class that staff member
// teaches in that cycle) -> dedupe across all staff to get the whole-school
// class list. Every endpoint in this chain is one we've confirmed live
// against your Compass instance.
//
// TODO(unverified) -- search "TODO(unverified)" for each site. Do not guess;
// each needs real data from the data leader before it can be fixed:
//   1. parseCyclesResponse() assumes response.d.cycles[] (with measures[] and
//      enrolments[].results[]). Needs a real GetCyclesByCycleIds response.
//   2. PAT/NAPLAN label strings in buildStudentsArray() are placeholders.
//   3. Growth (g) and prev{} are always null -- no source wired yet.
//   4. No endpoint found yet to list PAT/NAPLAN cycles; IDs are typed into the
//      overlay bar (remembered). Use "Check data shape" to capture #1/#2 safely.
//
// STILL MANUAL / UNVERIFIED:
//   - PAT/NAPLAN cycle IDs -- no confirmed endpoint lists these, so you still
//     paste them in (look them up via "Selected Cycles" in a Results Grid).
//   - PAT/NAPLAN measure label strings in buildStudentsArray() -- still
//     placeholders. Fix once you send a full GetCyclesByCycleIds response.
//   - entityId for GetReportReviewerBlob is taken from the activity's `id`
//     field (entityId: a.id) -- confirm if TJ results come back empty.
// ============================================================================

(function () {
  'use strict';

  // Loaded from the Compass Tools menu (compass-tools.js) instead of
  // Tampermonkey: open the dashboard straight away, no floating button.
  var FROM_LAUNCHER = !!window.__crusoeToolsLaunch;
  window.__crusoeToolsLaunch = false;

  if (window.__lndashLiveLoaded) {
    // Second click from the menu: just reopen the existing overlay.
    var existingOverlay = document.getElementById('lndash-overlay');
    if (FROM_LAUNCHER && existingOverlay) existingOverlay.style.display = 'flex';
    return;
  }
  window.__lndashLiveLoaded = true;

  // Data-free index.html (STUDENTS = []), inlined at build time so nothing is
  // fetched at runtime. Student data is injected in-browser only.
  var DASHBOARD_TEMPLATE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\">\n<title>Literacy & Numeracy Dashboard</title>\n<link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js\"></script>\n<style>\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}\nbody{font-family:'DM Sans',system-ui,sans-serif;font-size:14px;background:#F1F5F9;color:#0F172A;min-height:100vh;}\n#header{background:#0F2847;color:#fff;padding:0 20px;display:flex;align-items:center;justify-content:space-between;height:48px;position:sticky;top:0;z-index:100;gap:12px;}\n.header-right{display:flex;align-items:center;gap:10px;flex-shrink:0;}\n.sync-badge{font-size:12px;background:rgba(255,255,255,0.1);border-radius:20px;padding:4px 12px;color:#86EFAC;white-space:nowrap;}\n#tab-nav{background:#0F2847;border-bottom:1px solid rgba(255,255,255,0.1);padding:0 20px;display:flex;gap:2px;}\n.tab-btn{color:rgba(255,255,255,0.55);background:none;border:none;padding:8px 14px;font-size:12px;font-weight:500;cursor:pointer;border-bottom:2px solid transparent;transition:all 0.15s;font-family:inherit;}\n.tab-btn:hover{color:#fff;}\n.tab-btn.active{color:#fff;border-bottom-color:#60A5FA;}\n#content{padding:10px 16px;max-width:1600px;margin:0 auto;}\n.tab-panel{display:none;}\n.tab-panel.active{display:block;}\n.filter-bar{display:flex;gap:6px;flex-wrap:wrap;align-items:center;background:#fff;border-radius:8px;padding:7px 12px;margin-bottom:10px;border:1px solid #E2E8F0;}\n.filter-bar select,.filter-bar input[type=text]{height:30px;border:1px solid #E2E8F0;border-radius:6px;padding:0 10px;font-size:13px;font-family:inherit;color:#0F172A;background:#fff;outline:none;cursor:pointer;}\n.filter-bar select:focus,.filter-bar input[type=text]:focus{border-color:#60A5FA;box-shadow:0 0 0 3px rgba(96,165,250,0.12);}\n.filter-bar input[type=text]{flex:1;min-width:160px;}\n.rag-key{display:flex;gap:6px;align-items:center;margin-left:auto;flex-shrink:0;}\n.rag-key>span:first-child{font-size:11px;color:#94A3B8;}\n.rag-exc{background:#004488;color:#FFFFFF;border-radius:4px;padding:2px 8px;font-size:12px;font-weight:500;display:inline-block;white-space:nowrap;}\n.rag-g{background:#88CCEE;color:#00264D;border-radius:4px;padding:2px 8px;font-size:12px;font-weight:500;display:inline-block;white-space:nowrap;}\n.rag-a{background:#EEDD88;color:#5C4A00;border-radius:4px;padding:2px 8px;font-size:12px;font-weight:500;display:inline-block;white-space:nowrap;}\n.rag-r{background:#FF4000;color:#FFFFFF;border-radius:4px;padding:2px 8px;font-size:12px;font-weight:500;display:inline-block;white-space:nowrap;}\n.rag-b{background:#F1F5F9;color:#475569;border-radius:4px;padding:2px 8px;font-size:12px;font-weight:500;display:inline-block;white-space:nowrap;}\n.rag-u{background:#F1F5F9;color:#64748B;border-radius:4px;padding:2px 7px;font-size:11px;font-weight:500;display:inline-block;white-space:nowrap;font-style:italic;}\n/* Full-cell fill for achievement columns */\n.rc{display:flex;align-items:center;justify-content:center;height:24px;min-height:unset;padding:0 2px;font-size:10px;font-weight:600;white-space:nowrap;box-sizing:border-box;}\n.rc-exc{background:#004488;color:#FFFFFF;}\n.rc-g{background:#88CCEE;color:#00264D;}\n.rc-a{background:#EEDD88;color:#5C4A00;}\n.rc-r{background:#FF4000;color:#FFFFFF;}\n.rc-u{background:#F1F5F9;color:#64748B;font-style:italic;font-size:10px;}\n.rc-n{color:#CBD5E1;font-size:11px;}\n.srow:hover .rc-exc{background:#003377;}\n.srow:hover .rc-g{background:#77BBDD;}\n.srow:hover .rc-a{background:#DDCC77;}\n.srow:hover .rc-r{background:#EE3800;}\n.srow.sel .rc-exc{background:#003377;}\n.srow.sel .rc-g{background:#77BBDD;}\n.srow.sel .rc-a{background:#DDCC77;}\n.srow.sel .rc-r{background:#EE3800;}\n/* Full-cell flag boxes */\n.flag-fill-exc{background:#004488;color:#FFFFFF;}\n.flag-fill-g{background:#88CCEE;color:#00264D;}\n.flag-fill-a{background:#EEDD88;color:#5C4A00;}\n.flag-fill-r{background:#FF4000;color:#FFFFFF;}\n.gw-exc{color:#004488;font-size:11px;font-weight:700;white-space:nowrap;}\n.gw-g{color:#1A7AAF;font-size:11px;font-weight:600;white-space:nowrap;}\n.gw-a{color:#8B6914;font-size:11px;font-weight:600;white-space:nowrap;}\n.gw-r{color:#CC2200;font-size:11px;font-weight:600;white-space:nowrap;}\n.cards-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px;margin-bottom:10px;}\n.metric-card{background:#fff;border-radius:8px;padding:10px 12px;border:1px solid #E2E8F0;}\n.metric-card .lbl{font-size:11px;color:#64748B;margin-bottom:4px;}\n.metric-card .val{font-size:18px;font-weight:600;color:#0F172A;line-height:1.1;}\n.metric-card .sub{font-size:11px;color:#94A3B8;margin-top:3px;}\n.table-wrap{background:#fff;border-radius:10px;border:1px solid #E2E8F0;overflow:hidden;}\n.table-scroll{overflow-x:auto;}\ntable{width:100%;border-collapse:collapse;font-size:12px;min-width:600px;}\ntable .t-grow{display:none;}\ntable.show-growth .t-grow{display:table-cell;}\ntable .col-grw{display:none;}\ntable.show-growth .col-grw{display:table-cell;}\nthead{background:#F8FAFC;}\nth{font-weight:500;color:#475569;white-space:normal;word-break:break-word;}\n.th-main{font-size:11px;text-transform:uppercase;letter-spacing:0.04em;color:#94A3B8;font-weight:500;}\n.th-lit{color:#1D4ED8;font-size:12px;font-weight:600;border-bottom:2px solid #BFDBFE !important;}\n.th-num{color:#15803D;font-size:12px;font-weight:600;border-bottom:2px solid #BBF7D0 !important;}\ntd,th{padding:0;vertical-align:middle;}\n.t-name{padding:7px 10px;font-weight:500;color:#0F172A;font-size:12px;}\n.t-form{padding:7px 4px;text-align:center;color:#64748B;font-size:11px;}\n.t-ach{text-align:center;padding:0;vertical-align:middle;height:24px;}.t-grow{text-align:center;padding:5px 2px;}\n.t-na{color:#CBD5E1;font-size:10px;}\n.t-bl2{border-left:2px solid #E2E8F0;}\n.t-bl{border-left:1px solid #F1F5F9;}\n/* heatmap toggle */\ntable.hm-mode .rc{font-size:0;min-height:28px;}\ntable.hm-mode .rc-exc{background:#004488;}\ntable.hm-mode .gw-num{display:none;}\ntable.hm-mode .t-grow{min-width:22px;}\n.hm-btn{height:28px;padding:0 10px;border-radius:6px;font-size:11px;font-weight:500;cursor:pointer;border:1px solid var(--color-border-secondary);background:var(--color-background-primary);color:var(--color-text-secondary);font-family:var(--font-sans);transition:all 0.15s;white-space:nowrap;}\n.hm-btn.on{background:#0F2847;color:#fff;border-color:#0F2847;}\n.srow{cursor:pointer;border-bottom:1px solid #F8FAFC;transition:background 0.1s;}\n.srow.srow-nas{background:#FFF3EF;}\n.srow.srow-nas:hover td{background:#FFE8E0!important;}\n.srow:hover td{background:#F8FAFC;}\n.srow.sel td{background:#EFF6FF;}\n.row-footer{font-size:11px;color:#94A3B8;padding:7px 12px;border-top:1px solid #F1F5F9;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;}\n#dpanel{background:#fff;border-radius:10px;border:1px solid #E2E8F0;padding:20px;margin-top:14px;}\n.detail-hdr{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:8px;}\n.avatar{width:42px;height:42px;border-radius:50%;background:#DBEAFE;display:flex;align-items:center;justify-content:center;font-weight:600;font-size:14px;color:#1D4ED8;flex-shrink:0;}\n.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;}\n.dom-lbl{font-size:11px;font-weight:600;letter-spacing:0.05em;margin-bottom:10px;}\n.dom-lbl.lit{color:#1D4ED8;}\n.dom-lbl.num{color:#15803D;}\n.dt{width:100%;border-collapse:collapse;}\n.dt td{padding:8px 0;font-size:13px;border-bottom:1px solid #F8FAFC;}\n.dt td:first-child{color:#64748B;width:170px;}\n.charts-filter{background:#fff;border-radius:10px;padding:10px 14px;margin-bottom:14px;border:1px solid #E2E8F0;display:flex;align-items:center;gap:10px;flex-wrap:wrap;}\n.charts-filter label{font-size:12px;color:#64748B;font-weight:500;}\n.charts-filter select{height:34px;border:1px solid #E2E8F0;border-radius:6px;padding:0 10px;font-size:13px;font-family:inherit;color:#0F172A;background:#fff;outline:none;cursor:pointer;}\n.charts-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;}\n.chart-card{background:#fff;border-radius:10px;border:1px solid #E2E8F0;padding:16px 18px;}\n.chart-title{font-size:13px;font-weight:600;color:#0F172A;}\n.chart-sub{font-size:11px;color:#94A3B8;margin-top:2px;margin-bottom:14px;}\n.chart-wrap{position:relative;height:220px;}\n.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;}\n.s-card{background:#fff;border-radius:10px;border:1px solid #E2E8F0;padding:20px;}\n.s-card h2{font-size:14px;font-weight:600;color:#0F172A;margin-bottom:3px;}\n.s-card .desc{font-size:12px;color:#94A3B8;margin-bottom:16px;}\n.fg{margin-bottom:13px;}\n.fg label{display:block;font-size:12px;font-weight:500;color:#475569;margin-bottom:5px;}\n.fg input,.fg select{width:100%;height:36px;border:1px solid #E2E8F0;border-radius:6px;padding:0 10px;font-size:13px;font-family:inherit;color:#0F172A;outline:none;}\n.fg input:focus{border-color:#60A5FA;box-shadow:0 0 0 3px rgba(96,165,250,0.1);}\n.t-row{display:grid;grid-template-columns:90px 1fr 1fr;gap:8px;align-items:center;margin-bottom:8px;font-size:12px;}\n.t-row span{color:#64748B;font-weight:500;}\n.t-row input{height:32px;border:1px solid #E2E8F0;border-radius:6px;padding:0 8px;font-size:12px;font-family:inherit;outline:none;width:100%;}\n.t-row input:focus{border-color:#60A5FA;}\n.t-hdrs{display:grid;grid-template-columns:90px 1fr 1fr;gap:8px;margin-bottom:6px;font-size:11px;color:#CBD5E1;font-weight:500;}\n.t-single{display:grid;grid-template-columns:120px 1fr;gap:8px;align-items:center;margin-bottom:8px;font-size:12px;}\n.t-single span{color:#64748B;font-weight:500;}\n.t-single input{height:32px;border:1px solid #E2E8F0;border-radius:6px;padding:0 8px;font-size:12px;font-family:inherit;outline:none;width:100%;}\n.t-single input:focus{border-color:#60A5FA;}\n.s-section{margin-bottom:18px;}\n.s-section h3{font-size:12px;font-weight:600;margin-bottom:10px;letter-spacing:0.04em;}\n.s-section h3.lit{color:#1D4ED8;}\n.s-section h3.num{color:#15803D;}\n.s-section p{font-size:12px;font-weight:600;color:#475569;margin-bottom:8px;margin-top:12px;}\n.import-zone{border:2px dashed #E2E8F0;border-radius:8px;padding:18px;text-align:center;cursor:pointer;transition:all 0.15s;margin-bottom:12px;}\n.import-zone:hover{border-color:#60A5FA;background:#F0F9FF;}\n.import-zone p{font-size:13px;color:#64748B;}\n.import-zone .hint{font-size:11px;color:#CBD5E1;margin-top:6px;}\n.btn{display:inline-flex;align-items:center;gap:6px;height:34px;padding:0 14px;border-radius:6px;font-size:13px;font-weight:500;cursor:pointer;border:1px solid #E2E8F0;background:#fff;color:#0F172A;font-family:inherit;transition:all 0.15s;white-space:nowrap;}\n.btn:hover{background:#F8FAFC;}\n.btn-primary{background:#0F2847;color:#fff;border-color:#0F2847;}\n.btn-primary:hover{background:#1B3A6B;}\n.btn-save{background:#16A34A;color:#fff;border-color:#16A34A;}\n.btn-save:hover{background:#15803D;}\n.btn-danger{background:#FEF2F2;color:#991B1B;border-color:#FECACA;}\n.btn-danger:hover{background:#FEE2E2;}\n.btn-sm{height:28px;padding:0 10px;font-size:12px;}\n/* Modal */\n#modal-overlay{position:fixed;inset:0;background:rgba(15,40,71,0.55);z-index:200;display:none;align-items:flex-start;justify-content:center;padding:30px 16px;overflow-y:auto;}\n#modal-overlay.open{display:flex;}\n.modal{background:#fff;border-radius:12px;width:100%;max-width:640px;margin:auto;overflow:hidden;}\n.modal-hdr{background:#0F2847;color:#fff;padding:16px 22px;display:flex;align-items:center;justify-content:space-between;}\n.modal-hdr h2{font-size:15px;font-weight:600;margin:0;color:#fff;}\n.modal-body{padding:20px 22px;}\n.modal-2col{display:grid;grid-template-columns:1fr 1fr;gap:10px;}\n.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px;padding-top:16px;border-top:1px solid #F1F5F9;}\n.m-section-lbl{font-size:11px;font-weight:600;letter-spacing:0.04em;margin:14px 0 8px;padding-top:14px;border-top:1px solid #F1F5F9;}\n.m-section-lbl.lit{color:#1D4ED8;}\n.m-section-lbl.num{color:#15803D;}\n.m-section-lbl.prev{color:#7C3AED;}\n/* Modal tabs */\n.modal-tabs{display:flex;gap:0;margin-bottom:16px;border:1px solid #E2E8F0;border-radius:7px;overflow:hidden;}\n.modal-tab{flex:1;padding:8px 12px;font-size:12px;font-weight:500;border:none;background:#F8FAFC;color:#64748B;cursor:pointer;font-family:inherit;transition:all 0.12s;}\n.modal-tab.active{background:#0F2847;color:#fff;}\n.modal-tab-panel{display:none;}\n.modal-tab-panel.active{display:block;}\n/* Growth tab */\n.growth-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;}\n.growth-card{background:#fff;border-radius:10px;border:1px solid #E2E8F0;padding:16px 18px;}\n.growth-card-title{font-size:13px;font-weight:600;color:#0F172A;margin-bottom:2px;}\n.growth-card-sub{font-size:11px;color:#94A3B8;margin-bottom:14px;}\n.growth-bar-wrap{margin-bottom:10px;}\n.growth-bar-label{display:flex;justify-content:space-between;font-size:11px;color:#64748B;margin-bottom:4px;}\n.growth-bar-track{background:#F1F5F9;border-radius:99px;height:8px;overflow:hidden;position:relative;}\n.growth-bar-fill{height:100%;border-radius:99px;transition:width 0.4s;}\n.growth-bar-expected{position:absolute;top:0;bottom:0;width:2px;background:#94A3B8;}\n.growth-summary{background:#F8FAFC;border-radius:10px;border:1px solid #E2E8F0;overflow:hidden;margin-bottom:14px;}\n.growth-summary table{width:100%;font-size:12px;}\n.growth-summary th{font-size:11px;font-weight:500;color:#94A3B8;padding:8px 14px;text-align:left;border-bottom:1px solid #F1F5F9;background:#F8FAFC;}\n.growth-summary td{padding:8px 14px;border-bottom:1px solid #F8FAFC;vertical-align:middle;}\n.growth-summary tr:last-child td{border:none;}\n/* Prev data badge */\n.prev-badge{display:inline-block;background:#EDE9FE;color:#6D28D9;font-size:10px;font-weight:600;padding:1px 6px;border-radius:3px;margin-left:6px;vertical-align:middle;}\n/* Domain flag columns */\n.th-flag-lit{background:#CCE8F8;color:#003366;font-size:10px;font-weight:600;letter-spacing:0.04em;border-left:2px solid #BFDBFE !important;white-space:nowrap;}\n.th-flag-num{background:#D4EDDA;color:#0A5C2A;font-size:10px;font-weight:600;letter-spacing:0.04em;border-left:2px solid #BBF7D0 !important;white-space:nowrap;}\n.flag-cell{text-align:center;padding:0;border-left:2px solid #E2E8F0;vertical-align:middle;}\n.srow:hover .flag-cell{}\n.srow.sel .flag-cell{}\n.flag-box{display:flex;align-items:center;justify-content:center;min-height:33px;font-size:12px;font-weight:700;}\n.flag-box-g{background:#DCFCE7;color:#166534;}\n.flag-box-a{background:#FEF9C3;color:#854D0E;}\n.flag-box-r{background:#FEE2E2;color:#991B1B;}\n.flag-box-n{background:#F1F5F9;color:#CBD5E1;}\n.flag-box-u{background:#F1F5F9;color:#64748B;font-size:9px;letter-spacing:-0.02em;}\n/* CSV Mapper */\n#mapper-overlay{position:fixed;inset:0;background:rgba(15,40,71,0.6);z-index:250;display:none;align-items:flex-start;justify-content:center;padding:30px 16px;overflow-y:auto;}\n#mapper-overlay.open{display:flex;}\n.mapper-modal{background:#fff;border-radius:14px;width:100%;max-width:720px;margin:auto;overflow:hidden;}\n.mapper-hdr{background:#0F2847;color:#fff;padding:18px 22px;display:flex;align-items:center;justify-content:space-between;}\n.mapper-hdr h2{font-size:15px;font-weight:600;margin:0;}\n.mapper-body{padding:20px 22px;max-height:85vh;overflow-y:auto;}\n.mapper-source{background:#F8FAFC;border:1px solid #E2E8F0;border-radius:8px;padding:10px 14px;margin-bottom:16px;font-size:12px;color:#475569;}\n.map-table{width:100%;border-collapse:collapse;margin-bottom:16px;}\n.map-table th{font-size:11px;font-weight:500;color:#94A3B8;text-align:left;padding:0 0 8px;border-bottom:1px solid #F1F5F9;}\n.map-table td{padding:5px 0;border-bottom:1px solid #F8FAFC;vertical-align:middle;}\n.map-table td:first-child{font-size:12px;font-weight:500;color:#0F172A;width:200px;padding-right:12px;}\n.map-table select{width:100%;height:30px;border:1px solid #E2E8F0;border-radius:5px;padding:0 8px;font-size:12px;font-family:inherit;color:#0F172A;background:#fff;outline:none;}\n.map-table select:focus{border-color:#60A5FA;}\n.map-table select.auto{border-color:#86EFAC;background:#F0FDF4;}\n.mapper-mode{display:flex;gap:8px;margin-bottom:18px;flex-wrap:wrap;}\n.mode-btn{flex:1;min-width:140px;border:1px solid #E2E8F0;border-radius:8px;padding:10px 12px;cursor:pointer;background:#fff;font-family:inherit;text-align:left;transition:all 0.15s;}\n.mode-btn:hover{border-color:#60A5FA;background:#F0F9FF;}\n.mode-btn.active{border-color:#1D4ED8;background:#EFF6FF;}\n.mode-btn .mt{font-size:12px;font-weight:600;color:#0F172A;display:block;}\n.mode-btn .ms{font-size:11px;color:#94A3B8;display:block;margin-top:2px;}\n.mapper-preview{background:#F8FAFC;border:1px solid #E2E8F0;border-radius:8px;padding:12px 14px;margin-bottom:16px;}\n.preview-table{width:100%;border-collapse:collapse;font-size:11px;}\n.preview-table th{background:#E2E8F0;padding:5px 8px;text-align:left;font-weight:500;color:#475569;white-space:nowrap;}\n.preview-table td{padding:4px 8px;border-bottom:1px solid #F1F5F9;color:#0F172A;white-space:nowrap;}\n.mapper-actions{display:flex;justify-content:space-between;align-items:center;padding-top:14px;border-top:1px solid #F1F5F9;}\n.map-sec{font-size:10px;font-weight:600;letter-spacing:0.05em;padding:10px 0 4px;color:#94A3B8;}\n.map-sec.lit{color:#1D4ED8;}\n.map-sec.num{color:#15803D;}\n.map-sec.prev{color:#7C3AED;}\n.toast{position:fixed;bottom:24px;right:24px;background:#0F2847;color:#fff;padding:10px 18px;border-radius:8px;font-size:13px;font-weight:500;z-index:300;opacity:0;transition:opacity 0.2s;pointer-events:none;}\n.toast.show{opacity:1;}\n@media(max-width:900px){\n  .detail-grid,.settings-grid,.charts-grid,.growth-grid{grid-template-columns:1fr;}\n  #content{padding:12px 14px;}\n}\n@media print{\n  #header,.tab-btn,.filter-bar,.rag-key,.btn,#dpanel,#tab-nav{display:none!important;}\n  body{background:#fff;}\n}\n\n.naplan-split-card{padding:8px 12px;min-width:140px;}\n.naplan-halves{display:flex;border-radius:7px;overflow:hidden;margin-top:5px;height:44px;}\n.nh-str{flex:1;background:#88CCEE;color:#00264D;display:flex;flex-direction:column;align-items:center;justify-content:center;}\n.nh-nas{flex:1;background:#FF4000;color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;}\n.nh-pct{font-size:16px;font-weight:700;line-height:1;}\n.nh-lbl{font-size:9px;font-weight:600;margin-top:2px;opacity:0.85;letter-spacing:0.04em;text-transform:uppercase;}\n\n/* Lit / Num section divider */\n.sec-div{border-left:3px solid #94A3B8 !important;}\n.th-lit-banner{background:#1D4ED8;color:#fff;font-size:11px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;padding:5px 8px;text-align:center;}\n.th-num-banner{background:#15803D;color:#fff;font-size:11px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;padding:5px 8px;text-align:center;}\n.th-flag-header{font-size:9px;letter-spacing:0.04em;text-transform:uppercase;font-weight:700;padding:3px 4px;}\n/* Compact metric cards */\n.cards-grid{overflow:visible;margin-bottom:0;}\n\n\n.metric-card{padding:8px 12px;min-width:120px;}\n.metric-card .val{font-size:16px;}\n.metric-card .lbl{font-size:10px;}\n/* Compact rows */\n.srow td{padding-top:0 !important;padding-bottom:0 !important;height:24px;line-height:24px;}\n.rc{min-height:27px;}\n.flag-box{min-height:27px;}\n/* Compact filter bar */\n.filter-bar{padding:5px 10px;margin-bottom:6px;}\n.filter-bar select,.filter-bar input[type=text]{height:28px;font-size:11px;}\n.hm-btn{height:26px;font-size:11px;padding:0 8px;}\n/* Header compaction */\n#header{height:42px;}\n.tab-btn{padding:6px 12px;font-size:12px;}\n\n.rc-r2{background:#FF4000;color:#fff;position:relative;}\n.rc-r2::after{content:'!';position:absolute;bottom:2px;right:3px;font-size:7px;line-height:1;opacity:0.95;}\n.rag-r2{background:#FF4000;color:#fff;border-radius:4px;padding:2px 8px;font-size:12px;font-weight:500;display:inline-block;white-space:nowrap;position:relative;}\n.rag-r2::after{content:'!';position:absolute;bottom:1px;right:2px;font-size:6px;}\n.flag-fill-r2{background:#FF4000;color:#fff;position:relative;}\n.flag-fill-r2::after{content:'!';position:absolute;bottom:2px;right:3px;font-size:7px;opacity:0.95;}\n.srow:hover .rc-r2{background:#EE3800;}\n.srow.sel .rc-r2{background:#EE3800;}\n\n\n\n\n\n\n\n\n\n\n.stat-cell{background:#0F2847;padding:0 !important;border:0;}\n.stat-cell.num-sec{border-left:3px solid #4B5563;}\n.cs-wrap{display:flex;height:32px;border-radius:0;overflow:hidden;}\n.cs-str{flex:1;background:#3B9CC7;display:flex;flex-direction:column;align-items:center;justify-content:center;border-right:1px solid #fff;}\n.cs-nas{flex:1;background:#E8420A;display:flex;flex-direction:column;align-items:center;justify-content:center;}\n.sp{font-size:11px;font-weight:700;color:#fff;line-height:1.1;}\n.sl{font-size:7px;font-weight:700;color:rgba(255,255,255,.9);line-height:1;text-transform:uppercase;}\n.cs-none{color:rgba(255,255,255,.3);font-size:10px;text-align:center;line-height:32px;}\n</style>\n</head>\n<body>\n<div id=\"header\">\n  <div>\n    <div id=\"hdr-title\" style=\"font-size:14px;font-weight:600;color:#fff;\">Crusoe College — Literacy &amp; Numeracy Dashboard</div>\n    <div id=\"hdr-sub\" style=\"font-size:12px;opacity:0.6;margin-top:1px;\">2026</div>\n  </div>\n  <div class=\"header-right\">\n    <span class=\"sync-badge\">● Compass connected</span>\n    <button class=\"btn btn-sm\" style=\"background:rgba(255,255,255,0.1);color:#fff;border-color:rgba(255,255,255,0.2);\" onclick=\"window.print()\">Print</button>\n    <button class=\"btn btn-sm btn-primary\" onclick=\"openModal()\">+ Add student</button>\n    <a href=\"YOUR_GOOGLE_DOC_URL\" target=\"_blank\" rel=\"noopener\" style=\"display:inline-flex;align-items:center;gap:5px;background:rgba(255,255,255,0.12);color:#fff;text-decoration:none;border-radius:6px;padding:5px 12px;font-size:12px;font-weight:500;border:1px solid rgba(255,255,255,0.2);transition:background 0.15s;\" onmouseover=\"this.style.background='rgba(255,255,255,0.2)'\" onmouseout=\"this.style.background='rgba(255,255,255,0.12)'\">&#128172; Feedback</a>\n  </div>\n</div>\n<div id=\"tab-nav\">\n  <button class=\"tab-btn active\" onclick=\"showTab('data',this)\">Data view</button>\n  <button class=\"tab-btn\" onclick=\"showTab('growth',this)\">Growth modelling</button>\n  <button class=\"tab-btn\" onclick=\"showTab('charts',this)\">Class charts</button>\n  <button class=\"tab-btn\" onclick=\"showTab('settings',this)\">Settings</button>\n</div>\n<div id=\"content\">\n\n<!-- DATA TAB -->\n<div id=\"tab-data\" class=\"tab-panel active\">\n  <div class=\"filter-bar\">\n    <select id=\"fSch\" onchange=\"updateCls();renderData()\"></select>\n    <select id=\"fYr\" onchange=\"updateCls();renderData()\"></select>\n    <select id=\"fCls\" onchange=\"renderData()\"></select>\n    <input id=\"fNm\" type=\"text\" placeholder=\"Search student name...\">\n    <select id=\"fAch\" onchange=\"renderData()\" title=\"Filter by achievement band\"><option value=\"\">All achievement</option><option value=\"exc\">★ Exceeding</option><option value=\"g\">Strong</option><option value=\"a\">Developing</option><option value=\"r\">NAS</option></select>\n    <select id=\"fGrw\" onchange=\"renderData()\" title=\"Filter by growth\"><option value=\"\">All growth</option><option value=\"high\">High growth</option><option value=\"expected\">Expected growth</option><option value=\"low\">Low growth</option></select>\n    <button class=\"hm-btn\" id=\"nasBtn\" onclick=\"toggleNAS(this)\" title=\"Show only students with NAS in any domain\">&#9888; NAS only</button>\n    <button class=\"hm-btn\" id=\"hmBtn\" onclick=\"toggleHeatmap(this)\" title=\"Colours only: see patterns across your class at a glance. Click again to show numbers.\">Colours only</button>\n    <div class=\"rag-key\">\n      <span>Key:</span>\n      <span class=\"rag-exc\" style=\"font-size:11px;padding:2px 8px;\">Exceeding</span>\n      <span class=\"rag-g\" style=\"font-size:11px;padding:2px 8px;\">Strong</span>\n      <span class=\"rag-a\" style=\"font-size:11px;padding:2px 8px;\">Developing</span>\n      <span class=\"rag-r\" style=\"font-size:11px;padding:2px 8px;\">NAS</span>\n    </div>\n  </div>\n  <div class=\"cards-grid\" id=\"cards\"></div>\n  <div class=\"table-wrap\">\n    <div class=\"table-scroll\">\n      <table id=\"tbl\">\n                                                <colgroup>\n          <col style=\"width:110px\"><col style=\"width:28px\">\n          <col style=\"width:56px\"><col class=\"t-grow\" style=\"width:0\">\n          <col style=\"width:56px\"><col class=\"t-grow\" style=\"width:0\">\n          <col style=\"width:56px\"><col class=\"t-grow\" style=\"width:0\">\n          <col style=\"width:56px\"><col class=\"t-grow\" style=\"width:0\">\n          <col style=\"width:56px\"><col class=\"t-grow\" style=\"width:0\">\n          <col style=\"width:56px\"><col class=\"t-grow\" style=\"width:0\">\n          <col style=\"width:56px\"><col class=\"t-grow\" style=\"width:0\">\n          <col style=\"width:56px\"><col class=\"t-grow\" style=\"width:0\">\n          <col style=\"width:56px\"><col class=\"t-grow\" style=\"width:0\">\n        </colgroup>\n        <thead>\n          <tr>\n            <th rowspan=\"3\" style=\"text-align:left;padding:6px 10px;background:#0F2847;color:#fff;font-size:11px;font-weight:700;min-width:110px;\">STUDENT</th>\n            <th rowspan=\"3\" style=\"text-align:center;padding:6px 4px;background:#0F2847;color:rgba(255,255,255,.65);font-size:9px;font-weight:600;width:28px;\">FM</th>\n            <th colspan=\"6\" style=\"text-align:center;padding:5px 4px;background:#1D4ED8;color:#fff;font-size:11px;font-weight:700;letter-spacing:.06em;\">LITERACY</th>\n            <th colspan=\"3\" style=\"text-align:center;padding:5px 4px;background:#15803D;color:#fff;font-size:11px;font-weight:700;letter-spacing:.06em;border-left:3px solid #4B5563;\">NUMERACY</th>\n          </tr>\n          <tr>\n            <th id=\"st-patr\"  class=\"stat-cell\" style=\"width:56px;\"></th>\n            <th id=\"st-nr\"    class=\"stat-cell\" style=\"width:56px;\"></th>\n            <th id=\"st-nw\"    class=\"stat-cell\" style=\"width:56px;\"></th>\n            <th id=\"st-etj\"   class=\"stat-cell\" style=\"width:56px;\"></th>\n            <th id=\"st-etjw\"  class=\"stat-cell\" style=\"width:56px;\"></th>\n            <th id=\"st-etjsl\" class=\"stat-cell\" style=\"width:56px;\"></th>\n            <th id=\"st-patm\"  class=\"stat-cell num-sec\" style=\"width:56px;\"></th>\n            <th id=\"st-nn\"    class=\"stat-cell\" style=\"width:56px;\"></th>\n            <th id=\"st-mtj\"   class=\"stat-cell\" style=\"width:56px;\"></th>\n          </tr>\n          <tr>\n            <th style=\"text-align:center;padding:4px 2px;font-size:9px;color:#374151;font-weight:500;background:#fff;border-bottom:2px solid #1D4ED8;line-height:1.35;\">PAT-R</th>\n            <th style=\"text-align:center;padding:4px 2px;font-size:9px;color:#374151;font-weight:500;background:#fff;border-bottom:2px solid #1D4ED8;line-height:1.35;\">NAPLAN<br>Reading</th>\n            <th style=\"text-align:center;padding:4px 2px;font-size:9px;color:#374151;font-weight:500;background:#fff;border-bottom:2px solid #1D4ED8;line-height:1.35;\">NAPLAN<br>Write</th>\n            <th style=\"text-align:center;padding:4px 2px;font-size:9px;color:#374151;font-weight:500;background:#fff;border-bottom:2px solid #1D4ED8;line-height:1.35;\">Reading TJ<br>S2 25</th>\n            <th style=\"text-align:center;padding:4px 2px;font-size:9px;color:#374151;font-weight:500;background:#fff;border-bottom:2px solid #1D4ED8;line-height:1.35;\">Writing TJ<br>S2 25</th>\n            <th style=\"text-align:center;padding:4px 2px;font-size:9px;color:#374151;font-weight:500;background:#fff;border-bottom:2px solid #1D4ED8;line-height:1.35;\">Speaking TJ<br>S2 25</th>\n            <th style=\"text-align:center;padding:4px 2px;font-size:9px;color:#374151;font-weight:500;background:#fff;border-bottom:2px solid #15803D;border-left:3px solid #4B5563;line-height:1.35;\">Maths PAT</th>\n            <th style=\"text-align:center;padding:4px 2px;font-size:9px;color:#374151;font-weight:500;background:#fff;border-bottom:2px solid #15803D;line-height:1.35;\">NAPLAN<br>Num</th>\n            <th style=\"text-align:center;padding:4px 2px;font-size:9px;color:#374151;font-weight:500;background:#fff;border-bottom:2px solid #15803D;line-height:1.35;\">Maths TJ<br>S2 25</th>\n          </tr>\n        </thead>\n        <tbody id=\"tbody\"></tbody>\n      </table>\n      <div class=\"row-footer\">\n        <span id=\"rowCount\"></span>\n        <div style=\"display:flex;gap:8px;\">\n          <span style=\"font-size:11px;color:#CBD5E1;align-self:center;\">&#128312; = calculated from previous data</span>\n          <button class=\"btn btn-sm\" onclick=\"exportCSV()\">Export CSV</button>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div id=\"dpanel\" style=\"display:none;\"></div>\n</div>\n\n<!-- GROWTH TAB -->\n<div id=\"tab-growth\" class=\"tab-panel\">\n  <div class=\"filter-bar\">\n    <select id=\"gSch\" onchange=\"renderGrowth()\"></select>\n    <select id=\"gYr\" onchange=\"renderGrowth()\"></select>\n    <select id=\"gCls\" onchange=\"renderGrowth()\"></select>\n    <select id=\"gDomain\" onchange=\"renderGrowth()\">\n      <option value=\"all\">All domains</option>\n      <option value=\"patr\">PAT-R</option>\n      <option value=\"patm\">PAT-M</option>\n      <option value=\"nr\">NAPLAN<br>Reading</option>\n      <option value=\"nn\">NAPLAN Numeracy</option>\n      <option value=\"etj\">English TJ</option>\n      <option value=\"mtj\">Maths TJ</option>\n    </select>\n    <div class=\"rag-key\">\n      <span>Growth vs expected:</span>\n      <span class=\"rag-exc\" style=\"font-size:11px;padding:2px 8px;\">Exceeding</span>\n      <span class=\"rag-g\" style=\"font-size:11px;padding:2px 8px;\">Strong</span>\n      <span class=\"rag-a\" style=\"font-size:11px;padding:2px 8px;\">Developing</span>\n      <span class=\"rag-r\" style=\"font-size:11px;padding:2px 8px;\">NAS</span>\n    </div>\n  </div>\n  <div id=\"growth-cards\" class=\"cards-grid\" style=\"grid-template-columns:repeat(auto-fit,minmax(150px,1fr));\"></div>\n  <div id=\"growth-summary\" class=\"growth-summary\" style=\"margin-bottom:14px;\"></div>\n  <div class=\"growth-grid\" id=\"growth-charts\"></div>\n  <div class=\"table-wrap\" id=\"growth-table-wrap\">\n    <div class=\"table-scroll\">\n      <table id=\"growth-table\" style=\"min-width:700px;\">\n        <thead>\n          <tr style=\"background:#F8FAFC;\">\n            <th style=\"text-align:left;padding:10px 16px;font-size:11px;color:#94A3B8;font-weight:500;\">Student</th>\n            <th style=\"text-align:center;padding:10px 8px;font-size:11px;color:#94A3B8;font-weight:500;\">Form</th>\n            <th style=\"text-align:center;padding:10px 8px;font-size:11px;color:#94A3B8;font-weight:500;\" id=\"gh1\">—</th>\n            <th style=\"text-align:center;padding:10px 8px;font-size:11px;color:#94A3B8;font-weight:500;\" id=\"gh2\">—</th>\n            <th style=\"text-align:center;padding:10px 8px;font-size:11px;color:#94A3B8;font-weight:500;\" id=\"gh3\">Actual growth</th>\n            <th style=\"text-align:center;padding:10px 8px;font-size:11px;color:#94A3B8;font-weight:500;\" id=\"gh4\">Expected</th>\n            <th style=\"text-align:center;padding:10px 8px;font-size:11px;color:#94A3B8;font-weight:500;\" id=\"gh5\">vs Expected</th>\n            <th style=\"text-align:center;padding:10px 8px;font-size:11px;color:#94A3B8;font-weight:500;\" id=\"gh6\">RAG</th>\n          </tr>\n        </thead>\n        <tbody id=\"growth-tbody\"></tbody>\n      </table>\n      <div class=\"row-footer\"><span id=\"growth-count\"></span></div>\n    </div>\n  </div>\n</div>\n\n<!-- CHARTS TAB -->\n<div id=\"tab-charts\" class=\"tab-panel\">\n  <div class=\"charts-filter\">\n    <label>Year level:</label><select id=\"chartYr\" onchange=\"renderCharts()\"></select>\n    <label>School:</label><select id=\"chartSch\" onchange=\"renderCharts()\"></select>\n    <span style=\"font-size:11px;color:#CBD5E1;margin-left:8px;\">Bars = class averages. Dashed lines = RAG thresholds.</span>\n  </div>\n  <div class=\"charts-grid\">\n    <div class=\"chart-card\"><div class=\"chart-title\">PAT-R — Achievement</div><div class=\"chart-sub\">Average scale score by class</div><div class=\"chart-wrap\"><canvas id=\"cPATR\" role=\"img\" aria-label=\"PAT-R average achievement by class\"></canvas></div></div>\n    <div class=\"chart-card\"><div class=\"chart-title\">PAT-M — Achievement</div><div class=\"chart-sub\">Average scale score by class</div><div class=\"chart-wrap\"><canvas id=\"cPATM\" role=\"img\" aria-label=\"PAT-M average achievement by class\"></canvas></div></div>\n    <div class=\"chart-card\"><div class=\"chart-title\">NAPLAN Reading — Achievement</div><div class=\"chart-sub\">Average score by class</div><div class=\"chart-wrap\"><canvas id=\"cNR\" role=\"img\" aria-label=\"NAPLAN Reading average by class\"></canvas></div></div>\n    <div class=\"chart-card\"><div class=\"chart-title\">NAPLAN Numeracy — Achievement</div><div class=\"chart-sub\">Average score by class</div><div class=\"chart-wrap\"><canvas id=\"cNN\" role=\"img\" aria-label=\"NAPLAN Numeracy average by class\"></canvas></div></div>\n    <div class=\"chart-card\"><div class=\"chart-title\">English TJ — Achievement</div><div class=\"chart-sub\">Average VC level by class</div><div class=\"chart-wrap\"><canvas id=\"cETJ\" role=\"img\" aria-label=\"English TJ average by class\"></canvas></div></div>\n    <div class=\"chart-card\"><div class=\"chart-title\">Maths TJ — Achievement</div><div class=\"chart-sub\">Average VC level by class</div><div class=\"chart-wrap\"><canvas id=\"cMTJ\" role=\"img\" aria-label=\"Maths TJ average by class\"></canvas></div></div>\n  </div>\n</div>\n\n<!-- SETTINGS TAB -->\n<div id=\"tab-settings\" class=\"tab-panel\">\n  <div style=\"background:#FEF9C3;border:1px solid #FBBF24;border-radius:8px;padding:10px 16px;margin-bottom:14px;display:flex;align-items:center;gap:10px;font-size:13px;\"><span style=\"font-size:18px;\">&#9888;</span><div><strong>Data leader settings</strong> - These thresholds affect every colour in the dashboard. Talk to your data coordinator before making changes. <a href=\"#\" onclick=\"resetToDefaults();return false\" style=\"color:#1D4ED8;text-decoration:underline;\">Reset to school defaults</a></div></div>\n  <div class=\"settings-grid\">\n    <div class=\"s-card\">\n      <h2>School information</h2>\n      <p class=\"desc\">Displayed in the dashboard header.</p>\n      <div class=\"fg\"><label>School name</label><input type=\"text\" id=\"setName\" placeholder=\"e.g. Riverside Primary School\"></div>\n      <div class=\"fg\"><label>Dashboard year</label><input type=\"text\" id=\"setYear\" placeholder=\"e.g. 2025\"></div>\n      <button class=\"btn btn-save\" onclick=\"saveSchoolInfo()\">Save school info</button>\n    </div>\n    <div class=\"s-card\">\n      <h2>Data management</h2>\n      <p class=\"desc\">Import from Compass, ACER or ACARA exports. Column mapping is handled in the next step.</p>\n      <div class=\"import-zone\" onclick=\"document.getElementById('csvFile').click()\">\n        <p>Click to import CSV</p>\n        <div class=\"hint\">Any CSV layout — you'll map columns in the next step. Supports current and previous period data in the same file.</div>\n      </div>\n      <input type=\"file\" id=\"csvFile\" accept=\".csv\" style=\"display:none\" onchange=\"openMapper(event)\">\n      <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n        <button class=\"btn\" onclick=\"downloadTemplate()\">Download CSV template</button>\n        <button class=\"btn btn-danger\" onclick=\"if(confirm('Clear ALL student data?'))clearData();\">Clear all data</button>\n      </div>\n    </div>\n\n    <div class=\"s-card\" style=\"grid-column:1/-1;\">\n      <h2>RAG thresholds &amp; expected growth</h2>\n      <p class=\"desc\"><strong>Achievement:</strong> Green = at/above upper value. Amber = between. Red = below lower.<br>\n      <strong>NAPLAN growth:</strong> compared against expected growth for that year-level transition (e.g. Yr3->Yr5). Green = meets/exceeds. Amber = within tolerance. Red = below.<br>\n      <strong>PAT growth:</strong> compared against expected annual scale-score gain. TJ growth: compared against expected VC level gain per year.</p>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:16px;\">\n        <div>\n          <div class=\"s-section\">\n            <h3 class=\"lit\">LITERACY — ACHIEVEMENT</h3>\n            <p>PAT-R Achievement</p>\n            <div class=\"t-hdrs\"><span></span><span class=\"rag-exc\" style=\"font-size:10px;padding:1px 6px;\">Exc &ge;</span><span class=\"rag-g\" style=\"font-size:10px;padding:1px 6px;\">Str &ge;</span></div>\n            <div class=\"t-row\"><span>Year 7</span><input type=\"number\" id=\"t_patr_7g\" placeholder=\"111\"><input type=\"number\" id=\"t_patr_7a\" placeholder=\"101\"></div>\n            <div class=\"t-row\"><span>Year 8</span><input type=\"number\" id=\"t_patr_8g\" placeholder=\"116\"><input type=\"number\" id=\"t_patr_8a\" placeholder=\"106\"></div>\n            <div class=\"t-row\"><span>Year 9</span><input type=\"number\" id=\"t_patr_9g\" placeholder=\"120\"><input type=\"number\" id=\"t_patr_9a\" placeholder=\"110\"></div>\n            <div class=\"t-row\"><span>Year 10</span><input type=\"number\" id=\"t_patr_10g\" placeholder=\"124\"><input type=\"number\" id=\"t_patr_10a\" placeholder=\"114\"></div>\n            <p>NAPLAN Reading Achievement</p>\n            <div class=\"t-hdrs\"><span></span><span class=\"rag-exc\" style=\"font-size:10px;padding:1px 6px;\">Exc &ge;</span><span class=\"rag-g\" style=\"font-size:10px;padding:1px 6px;\">Str &ge;</span></div>\n            <div class=\"t-row\"><span>Year 3</span><input type=\"number\" id=\"t_nr3_g\"><input type=\"number\" id=\"t_nr3_a\"></div>\n            <div class=\"t-row\"><span>Year 5</span><input type=\"number\" id=\"t_nr5_g\"><input type=\"number\" id=\"t_nr5_a\"></div>\n            <div class=\"t-row\"><span>Year 7</span><input type=\"number\" id=\"t_nr7_g\"><input type=\"number\" id=\"t_nr7_a\"></div>\n            <p>English TJ — expected VC level</p>\n            <div class=\"t-hdrs\"><span></span><span style=\"font-size:11px;color:#94A3B8;\">Expected</span><span></span></div>\n            <div class=\"t-single\"><span>Year 3</span><input type=\"number\" id=\"t_etj3\"></div>\n            <div class=\"t-single\"><span>Year 4</span><input type=\"number\" id=\"t_etj4\"></div>\n            <div class=\"t-single\"><span>Year 5</span><input type=\"number\" id=\"t_etj5\"></div>\n            <div class=\"t-single\"><span>Year 6</span><input type=\"number\" id=\"t_etj6\"></div>\n            <div class=\"t-single\"><span>Year 7</span><input type=\"number\" id=\"t_etj7\"></div>\n            <div class=\"t-single\"><span>Year 8</span><input type=\"number\" id=\"t_etj8\"></div>\n            <div class=\"t-single\"><span>Year 9</span><input type=\"number\" id=\"t_etj9\"></div>\n            <div class=\"t-single\"><span>Year 10</span><input type=\"number\" id=\"t_etj10\"></div>\n          </div>\n\n          <div class=\"s-section\" style=\"border-top:1px solid #F1F5F9;padding-top:14px;\">\n            <h3 style=\"color:#7C3AED;font-size:12px;font-weight:600;margin-bottom:10px;letter-spacing:0.04em;\">LITERACY — EXPECTED GROWTH</h3>\n            <p>PAT-R growth per year (scale score)</p>\n            <div class=\"t-single\"><span>Expected gain</span><input type=\"number\" id=\"t_patr_exp_g\"></div>\n            <div class=\"t-single\"><span>Tolerance (±)</span><input type=\"number\" id=\"t_patr_exp_tol\"></div>\n            <p>NAPLAN Reading expected growth</p>\n            <div class=\"t-hdrs\"><span></span><span style=\"font-size:11px;color:#94A3B8;\">Expected</span><span style=\"font-size:11px;color:#94A3B8;\">Tolerance</span></div>\n            <div class=\"t-row\"><span>Yr 3 -> Yr 5</span><input type=\"number\" id=\"t_nr_35_exp\"><input type=\"number\" id=\"t_nr_35_tol\"></div>\n            <div class=\"t-row\"><span>Yr 5 -> Yr 7</span><input type=\"number\" id=\"t_nr_57_exp\"><input type=\"number\" id=\"t_nr_57_tol\"></div>\n            <p>English TJ growth thresholds <span style=\"font-size:10px;color:#94A3B8;\">(&#8805;0.5=Green, >0=Amber, &#8804;0=Red)</span></p>\n            <div class=\"t-single\"><span>Expected gain</span><input type=\"number\" id=\"t_etj_exp_g\" step=\"0.5\"></div>\n            <div class=\"t-single\"><span>Tolerance (±)</span><input type=\"number\" id=\"t_etj_exp_tol\" step=\"0.5\"></div>\n          </div>\n        </div>\n\n        <div>\n          <div class=\"s-section\">\n            <h3 class=\"num\">NUMERACY — ACHIEVEMENT</h3>\n            <p>PAT-M Achievement</p>\n            <div class=\"t-hdrs\"><span></span><span class=\"rag-exc\" style=\"font-size:10px;padding:1px 6px;\">Exc &ge;</span><span class=\"rag-g\" style=\"font-size:10px;padding:1px 6px;\">Str &ge;</span></div>\n            <div class=\"t-row\"><span>Year 7</span><input type=\"number\" id=\"t_patm_7g\" placeholder=\"111\"><input type=\"number\" id=\"t_patm_7a\" placeholder=\"101\"></div>\n            <div class=\"t-row\"><span>Year 8</span><input type=\"number\" id=\"t_patm_8g\" placeholder=\"116\"><input type=\"number\" id=\"t_patm_8a\" placeholder=\"106\"></div>\n            <div class=\"t-row\"><span>Year 9</span><input type=\"number\" id=\"t_patm_9g\" placeholder=\"120\"><input type=\"number\" id=\"t_patm_9a\" placeholder=\"110\"></div>\n            <div class=\"t-row\"><span>Year 10</span><input type=\"number\" id=\"t_patm_10g\" placeholder=\"124\"><input type=\"number\" id=\"t_patm_10a\" placeholder=\"114\"></div>\n            <p>NAPLAN Numeracy Achievement</p>\n            <div class=\"t-hdrs\"><span></span><span class=\"rag-exc\" style=\"font-size:10px;padding:1px 6px;\">Exc &ge;</span><span class=\"rag-g\" style=\"font-size:10px;padding:1px 6px;\">Str &ge;</span></div>\n            <div class=\"t-row\"><span>Year 3</span><input type=\"number\" id=\"t_nn3_g\"><input type=\"number\" id=\"t_nn3_a\"></div>\n            <div class=\"t-row\"><span>Year 5</span><input type=\"number\" id=\"t_nn5_g\"><input type=\"number\" id=\"t_nn5_a\"></div>\n            <div class=\"t-row\"><span>Year 7</span><input type=\"number\" id=\"t_nn7_g\"><input type=\"number\" id=\"t_nn7_a\"></div>\n            <p>Maths TJ — expected VC level</p>\n            <div class=\"t-hdrs\"><span></span><span style=\"font-size:11px;color:#94A3B8;\">Expected</span><span></span></div>\n            <div class=\"t-single\"><span>Year 3</span><input type=\"number\" id=\"t_mtj3\"></div>\n            <div class=\"t-single\"><span>Year 4</span><input type=\"number\" id=\"t_mtj4\"></div>\n            <div class=\"t-single\"><span>Year 5</span><input type=\"number\" id=\"t_mtj5\"></div>\n            <div class=\"t-single\"><span>Year 6</span><input type=\"number\" id=\"t_mtj6\"></div>\n            <div class=\"t-single\"><span>Year 7</span><input type=\"number\" id=\"t_mtj7\"></div>\n            <div class=\"t-single\"><span>Year 8</span><input type=\"number\" id=\"t_mtj8\"></div>\n            <div class=\"t-single\"><span>Year 9</span><input type=\"number\" id=\"t_mtj9\"></div>\n            <div class=\"t-single\"><span>Year 10</span><input type=\"number\" id=\"t_mtj10\"></div>\n          </div>\n\n          <div class=\"s-section\" style=\"border-top:1px solid #F1F5F9;padding-top:14px;\">\n            <h3 style=\"color:#7C3AED;font-size:12px;font-weight:600;margin-bottom:10px;letter-spacing:0.04em;\">NUMERACY — EXPECTED GROWTH</h3>\n            <p>PAT-M growth per year (scale score)</p>\n            <div class=\"t-single\"><span>Expected gain</span><input type=\"number\" id=\"t_patm_exp_g\"></div>\n            <div class=\"t-single\"><span>Tolerance (±)</span><input type=\"number\" id=\"t_patm_exp_tol\"></div>\n            <p>NAPLAN Numeracy expected growth</p>\n            <div class=\"t-hdrs\"><span></span><span style=\"font-size:11px;color:#94A3B8;\">Expected</span><span style=\"font-size:11px;color:#94A3B8;\">Tolerance</span></div>\n            <div class=\"t-row\"><span>Yr 3 -> Yr 5</span><input type=\"number\" id=\"t_nn_35_exp\"><input type=\"number\" id=\"t_nn_35_tol\"></div>\n            <div class=\"t-row\"><span>Yr 5 -> Yr 7</span><input type=\"number\" id=\"t_nn_57_exp\"><input type=\"number\" id=\"t_nn_57_tol\"></div>\n            <p>Maths TJ growth thresholds <span style=\"font-size:10px;color:#94A3B8;\">(&#8805;0.5=Green, >0=Amber, &#8804;0=Red)</span></p>\n            <div class=\"t-single\"><span>Expected gain</span><input type=\"number\" id=\"t_mtj_exp_g\" step=\"0.5\"></div>\n            <div class=\"t-single\"><span>Tolerance (±)</span><input type=\"number\" id=\"t_mtj_exp_tol\" step=\"0.5\"></div>\n          </div>\n        </div>\n      </div>\n\n      <div style=\"display:flex;gap:8px;margin-top:8px;padding-top:16px;border-top:1px solid #F1F5F9;\">\n        <button class=\"btn btn-save\" onclick=\"saveThresholds()\">Save &amp; apply thresholds</button>\n        <button class=\"btn\" onclick=\"if(confirm('Reset to defaults?'))resetThresholds();\">Reset to defaults</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n</div><!-- /content -->\n\n<!-- STUDENT MODAL -->\n<div id=\"modal-overlay\">\n  <div class=\"modal\">\n    <div class=\"modal-hdr\">\n      <h2 id=\"modal-title\">Add student</h2>\n      <button class=\"btn btn-sm\" style=\"background:rgba(255,255,255,0.12);color:#fff;border-color:rgba(255,255,255,0.2);\" onclick=\"closeModal()\">Cancel</button>\n    </div>\n    <div class=\"modal-body\">\n      <input type=\"hidden\" id=\"modal-id\">\n      <div class=\"modal-2col\" style=\"margin-bottom:10px;\">\n        <div class=\"fg\"><label>Full name *</label><input type=\"text\" id=\"m_name\" placeholder=\"e.g. Amelia Chen\"></div>\n        <div class=\"fg\"><label>Form / Class</label><input type=\"text\" id=\"m_form\" placeholder=\"e.g. 5A\"></div>\n        <div class=\"fg\"><label>Year level</label><select id=\"m_yr\"><option value=\"3\">Year 3</option><option value=\"4\">Year 4</option><option value=\"5\" selected>Year 5</option><option value=\"6\">Year 6</option><option value=\"7\">Year 7</option></select></div>\n        <div class=\"fg\"><label>School</label><input type=\"text\" id=\"m_sch\" placeholder=\"e.g. Riverside PS\"></div>\n      </div>\n\n      <div class=\"modal-tabs\">\n        <button class=\"modal-tab active\" onclick=\"switchModalTab('current',this)\">Current data</button>\n        <button class=\"modal-tab\" onclick=\"switchModalTab('prev',this)\">Previous data <span style=\"font-size:10px;opacity:0.7;\">(for growth)</span></button>\n      </div>\n\n      <div id=\"mtab-current\" class=\"modal-tab-panel active\">\n        <div class=\"m-section-lbl lit\">LITERACY</div>\n        <div class=\"modal-2col\">\n          <div class=\"fg\"><label>PAT-R Achievement</label><input type=\"number\" id=\"m_patr_a\" placeholder=\"Score\"></div>\n          <div class=\"fg\"><label>PAT-R Growth <span style=\"font-size:10px;color:#94A3B8;\">(auto if prev set)</span></label><input type=\"number\" id=\"m_patr_g\" placeholder=\"Manual override\"></div>\n          <div class=\"fg\"><label>NAPLAN Reading Ach</label><input type=\"text\" id=\"m_nr_a\" placeholder=\"Score or Exceeding/Strong/Developing/NAS\"></div>\n          <div class=\"fg\"><label>NAPLAN Reading Growth</label><input type=\"number\" id=\"m_nr_g\" placeholder=\"Manual override\"></div>\n          <div class=\"fg\"><label>NAPLAN Writing Ach</label><input type=\"text\" id=\"m_nw_a\" placeholder=\"Exceeding/Strong/Developing/NAS\"></div>\n          <div class=\"fg\"><label>NAPLAN Writing Growth</label><input type=\"number\" id=\"m_nw_g\" placeholder=\"Manual override\"></div>\n          <div class=\"fg\"><label>English TJ Achievement</label><input type=\"number\" id=\"m_etj_a\" placeholder=\"VC Level number\"></div>\n          <div class=\"fg\"><label>English TJ Growth <span style=\"font-size:10px;color:#94A3B8;\">(auto if prev set)</span></label><input type=\"number\" id=\"m_etj_g\" placeholder=\"Manual override\"></div>\n        </div>\n        <div class=\"m-section-lbl num\">NUMERACY</div>\n        <div class=\"modal-2col\">\n          <div class=\"fg\"><label>PAT-M Achievement</label><input type=\"number\" id=\"m_patm_a\" placeholder=\"Score\"></div>\n          <div class=\"fg\"><label>PAT-M Growth <span style=\"font-size:10px;color:#94A3B8;\">(auto if prev set)</span></label><input type=\"number\" id=\"m_patm_g\" placeholder=\"Manual override\"></div>\n          <div class=\"fg\"><label>NAPLAN Numeracy Ach</label><input type=\"number\" id=\"m_nn_a\" placeholder=\"Score (blank if N/A)\"></div>\n          <div class=\"fg\"><label>NAPLAN Numeracy Growth <span style=\"font-size:10px;color:#94A3B8;\">(auto if prev set)</span></label><input type=\"number\" id=\"m_nn_g\" placeholder=\"Manual override\"></div>\n          <div class=\"fg\"><label>Maths TJ Achievement</label><input type=\"number\" id=\"m_mtj_a\" placeholder=\"VC Level number\"></div>\n          <div class=\"fg\"><label>Maths TJ Growth <span style=\"font-size:10px;color:#94A3B8;\">(auto if prev set)</span></label><input type=\"number\" id=\"m_mtj_g\" placeholder=\"Manual override\"></div>\n        </div>\n      </div>\n\n      <div id=\"mtab-prev\" class=\"modal-tab-panel\">\n        <div style=\"background:#F5F3FF;border:1px solid #DDD6FE;border-radius:8px;padding:10px 14px;margin-bottom:14px;font-size:12px;color:#5B21B6;\">\n          Enter previous assessment data to enable auto-calculated growth. NAPLAN previous data should be from 2 years ago (e.g. Year 3 results for a current Year 5 student). PAT and TJ previous data should be from the last testing period.\n        </div>\n        <div class=\"m-section-lbl prev\">PREVIOUS NAPLAN</div>\n        <div class=\"modal-2col\">\n          <div class=\"fg\"><label>Previous NAPLAN year level</label><select id=\"m_naplan_prev_yr\"><option value=\"\">Not yet tested</option><option value=\"3\">Year 3</option><option value=\"5\">Year 5</option><option value=\"7\">Year 7</option></select></div>\n          <div class=\"fg\"><label>Year tested</label><input type=\"number\" id=\"m_naplan_prev_testyear\" placeholder=\"e.g. 2023\"></div>\n          <div class=\"fg\"><label>Prev NAPLAN Reading</label><input type=\"number\" id=\"m_prev_nr\" placeholder=\"Score\"></div>\n          <div class=\"fg\"><label>Prev NAPLAN Numeracy</label><input type=\"number\" id=\"m_prev_nn\" placeholder=\"Score\"></div>\n        </div>\n        <div class=\"m-section-lbl prev\">PREVIOUS PAT &amp; TEACHER JUDGEMENT</div>\n        <div class=\"modal-2col\">\n          <div class=\"fg\"><label>Prev PAT-R Score</label><input type=\"number\" id=\"m_prev_patr\" placeholder=\"Scale score\"></div>\n          <div class=\"fg\"><label>Prev PAT-M Score</label><input type=\"number\" id=\"m_prev_patm\" placeholder=\"Scale score\"></div>\n          <div class=\"fg\"><label>Prev English TJ</label><input type=\"number\" id=\"m_prev_etj\" placeholder=\"VC Level number\"></div>\n          <div class=\"fg\"><label>Prev Maths TJ</label><input type=\"number\" id=\"m_prev_mtj\" placeholder=\"VC Level number\"></div>\n        </div>\n      </div>\n\n      <div class=\"modal-actions\">\n        <button class=\"btn\" onclick=\"closeModal()\">Cancel</button>\n        <button class=\"btn btn-primary\" onclick=\"saveStudent()\">Save student</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- CSV MAPPER MODAL -->\n<div id=\"mapper-overlay\">\n  <div class=\"mapper-modal\">\n    <div class=\"mapper-hdr\">\n      <div><h2>Map your CSV columns</h2><p id=\"mapper-filename\" style=\"font-size:12px;opacity:0.6;margin:3px 0 0;\"></p></div>\n      <button class=\"btn btn-sm\" style=\"background:rgba(255,255,255,0.12);color:#fff;border-color:rgba(255,255,255,0.2);\" onclick=\"closeMapper()\">Cancel</button>\n    </div>\n    <div class=\"mapper-body\">\n      <div class=\"mapper-source\" id=\"mapper-source-info\"></div>\n      <div style=\"font-size:11px;font-weight:600;color:#94A3B8;margin-bottom:10px;letter-spacing:0.03em;\">COLUMN MAPPING — match your CSV headers to each dashboard field</div>\n      <table class=\"map-table\">\n        <thead><tr><th>Dashboard field</th><th>Your CSV column</th><th style=\"text-align:center;width:60px;\">Auto?</th></tr></thead>\n        <tbody id=\"map-rows\"></tbody>\n      </table>\n      <div style=\"font-size:11px;font-weight:600;color:#94A3B8;margin:14px 0 10px;padding-top:14px;border-top:1px solid #F1F5F9;letter-spacing:0.03em;\">IMPORT MODE</div>\n      <div class=\"mapper-mode\">\n        <button class=\"mode-btn active\" id=\"mode-add\" onclick=\"setMode('add',this)\"><span class=\"mt\">Add to existing</span><span class=\"ms\">Append rows — keep current data</span></button>\n        <button class=\"mode-btn\" id=\"mode-replace\" onclick=\"setMode('replace',this)\"><span class=\"mt\">Replace matching</span><span class=\"ms\">Update students by name</span></button>\n        <button class=\"mode-btn\" id=\"mode-overwrite\" onclick=\"setMode('overwrite',this)\"><span class=\"mt\">Replace all data</span><span class=\"ms\">Clear existing, import fresh</span></button>\n      </div>\n      <div class=\"mapper-preview\">\n        <p style=\"font-size:11px;font-weight:600;color:#64748B;margin-bottom:8px;letter-spacing:0.03em;\">PREVIEW — first 3 rows</p>\n        <div style=\"height:1px;background:#E2E8F0;margin:12px 0 10px;\"></div>\n  <div style=\"overflow-x:auto;overflow-y:auto;flex:1;min-height:0;\"><table class=\"preview-table\" id=\"preview-table\"></table></div>\n      </div>\n      <div class=\"mapper-actions\">\n        <span style=\"font-size:12px;color:#64748B;\" id=\"mapper-count\"></span>\n        <div style=\"display:flex;gap:8px;\">\n          <button class=\"btn\" onclick=\"closeMapper()\">Cancel</button>\n          <button class=\"btn btn-primary\" onclick=\"runImport()\">Import students</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\n// =====================================================================\n// SAMPLE DATA\n// prev = previous period data for growth calculation\n// naplan_prev_yr = year level when NAPLAN was previously sat (e.g. 3 for a current Yr5 student)\n// =====================================================================\nvar STUDENTS = [];\n\n// =====================================================================\n// DEFAULT THRESHOLDS\n// =====================================================================\n\n// -- PAT National Percentile Thresholds (ACER Table 5) -----------------------\n// exc = 75th percentile, str = 25th percentile, dev = 5th percentile\nvar PAT_THRESHOLDS = {\n  r:{7:{exc:139.4,str:121.9,dev:109.4},8:{exc:141.2,str:124.0,dev:111.6},9:{exc:143.9,str:127.2,dev:115.2},10:{exc:148.7,str:132.2,dev:120.4}},\n  m:{7:{exc:140.4,str:122.7,dev:109.9},8:{exc:142.0,str:125.3,dev:113.3},9:{exc:144.1,str:126.7,dev:114.2},10:{exc:145.4,str:128.7,dev:116.6}}\n};\nvar DEFAULT_T={\n  patr:{7:{g:111,a:101},8:{g:116,a:106},9:{g:120,a:110},10:{g:124,a:114}},\n  patm:{7:{g:111,a:101},8:{g:116,a:106},9:{g:120,a:110},10:{g:124,a:114}},\n  nr:{3:{g:350,a:290},5:{g:480,a:420},7:{g:545,a:485}},\n  nn:{3:{g:360,a:300},5:{g:490,a:430},7:{g:555,a:495}},\n  etj:{3:2,4:3,5:4,6:5,7:7,8:8,9:9,10:10},etjw:{3:2,4:3,5:4,6:5,7:7,8:8,9:9,10:10},etjsl:{3:2,4:3,5:4,6:5,7:7,8:8,9:9,10:10},mtj:{3:2,4:3,5:4,6:5,7:7,8:8,9:9,10:10},\n  // Expected growth\n  patr_gr:{exp:8,tol:4},patm_gr:{exp:8,tol:4},\n  nr_gr:{'35':{exp:90,tol:25},'57':{exp:65,tol:20}},\n  nn_gr:{'35':{exp:95,tol:25},'57':{exp:65,tol:20}},\n  etj_gr:{exp:0.5,tol:0.4999},mtj_gr:{exp:0.5,tol:0.4999}\n};\nvar T=JSON.parse(JSON.stringify(DEFAULT_T));\nvar schoolName='Crusoe College';\nvar dashYear='2026';\n\n// =====================================================================\n// GROWTH ENGINE\n// Returns calculated growth for each domain, and expected growth where applicable\n// =====================================================================\nfunction calcGrowth(s){\n  var p=s.prev||{};\n  function diff(cur,prv){return(cur!==null&&cur!==undefined&&prv!==null&&prv!==undefined)?Math.round((cur-prv)*10)/10:null;}\n\n  var patrG=diff(s.patr.a,p.patr);\n  var patmG=diff(s.patm.a,p.patm);\n  var nrG=diff(s.nr.a,p.nr);\n  var nnG=diff(s.nn.a,p.nn);\n  var etjG=diff(s.etj.a,p.etj);\n  var mtjG=diff(s.mtj.a,p.mtj);\n\n  // NAPLAN expected growth by transition\n  function naplExp(domain){\n    if(!p.naplan_yr)return null;\n    var key=p.naplan_yr+''+s.yr; // e.g. '35'\n    var tbl=domain==='nr'?T.nr_gr:T.nn_gr;\n    return tbl[key]||null;\n  }\n\n  return{\n    patr:{g:patrG,hasPrev:p.patr!==null&&p.patr!==undefined,exp:T.patr_gr},\n    patm:{g:patmG,hasPrev:p.patm!==null&&p.patm!==undefined,exp:T.patm_gr},\n    nr:{g:nrG,hasPrev:p.nr!==null&&p.nr!==undefined,exp:naplExp('nr'),prevYr:p.naplan_yr},\n    nn:{g:nnG,hasPrev:p.nn!==null&&p.nn!==undefined,exp:naplExp('nn'),prevYr:p.naplan_yr},\n    nw:{g:null,hasPrev:false,exp:null},\n    etj:{g:etjG,hasPrev:p.etj!==null&&p.etj!==undefined,exp:T.etj_gr},\n    mtj:{g:mtjG,hasPrev:p.mtj!==null&&p.mtj!==undefined,exp:T.mtj_gr},\n  };\n}\n\n// TJ growth RAG: >=0.5=green, >0=amber, <=0=red (per school policy)\nfunction rGrowthTJ(v){\n  if(v===null||v===undefined)return null;\n  if(v>=1.0)return'exc';\n  if(v>=0.5)return'g';\n  if(v>0)return'a';\n  return'r';\n}\n// PAT/NAPLAN growth RAG vs expected\nfunction rGrowth(actualG,exp,isNaplan){\n  if(actualG===null)return null;\n  if(!exp)return actualG>0?'g':actualG===0?'a':'r';\n  var expected=exp.exp,tol=exp.tol;\n  if(actualG>=expected+tol)return'exc';\n  if(actualG>=expected)return'g';\n  if(actualG>=0)return'a';\n  return'r';\n}\n\n// =====================================================================\n// ACHIEVEMENT RAG\n// =====================================================================\nfunction rPAT(v,type,yr){\n  if(v===null||v===undefined)return null;\n  var k=type==='patr'?'r':type==='patm'?'m':type;\n  var tbl=PAT_THRESHOLDS[k];\n  if(!tbl)return null;\n  var th=tbl[yr]||tbl[8]||{exc:141.2,str:124.0,dev:111.6};\n  if(v>=th.exc)return'exc';\n  if(v>=th.str)return'g';\n  if(v>=th.dev)return'a';\n  return'r';\n}\nfunction rNAPLAN(v,yr,numFn){\n  if(v===null||v===undefined)return null;\n  if(typeof v==='string'||isNaN(Number(v))){\n    var lv=String(v).toLowerCase().trim();\n    if(lv==='exceeding')return'exc';\n    if(lv==='strong')return'g';\n    if(lv==='developing')return'a';\n    if(lv==='needs additional support')return'r';\n    if(lv==='unknown level')return'u';\n    return null;\n  }\n  return numFn(Number(v),yr);\n}\nfunction rNR(v,yr){return rNAPLAN(v,yr,function(n,y){var t=T.nr[y]||T.nr[5];return n>=t.g?'g':n>=t.a?'a':'r';});}\nfunction rNN(v,yr){return rNAPLAN(v,yr,function(n,y){var t=T.nn[y]||T.nn[5];return n>=t.g?'g':n>=t.a?'a':'r';});}\nfunction rNW(v){return rNAPLAN(v,null,function(){return null;});}\nfunction rTJ(v,yr,type){\n  if(v===null||v===undefined)return null;\n  var e=yr-1;\n  if(v>e) return'exc';\n  if(v>=e) return'g';\n  if(v>=e-0.5) return'a';\n  if(v>=e-1.5) return'r';\n  return'r2';\n}\n\n// Average a set of RAG strings (g=2, a=1, r=0). Nulls excluded.\n// Result: avg>=1.5 -> g, avg>=0.5 -> a, else r. Returns null if no data.\n\nfunction abbrevNAPLAN(v){\n  if(v===null||v===undefined)return null;\n  var lv=String(v).toLowerCase().trim();\n  if(lv==='exceeding')return'Exc';\n  if(lv==='strong')return'Str';\n  if(lv==='developing')return'Dev';\n  if(lv==='needs additional support')return'NAS';\n  if(lv==='unknown level')return'?';\n  return v;\n}\nfunction avgRAG(rags){\n  var scored=rags.filter(function(r){return r==='exc'||r==='g'||r==='a'||r==='r'||r==='r2';});\n  if(!scored.length)return null;\n  if(scored.every(function(r){return r==='exc';}))return'exc';\n  var vals=scored.map(function(r){return r==='exc'?2:r==='g'?2:r==='a'?1:0;});\n  var avg=vals.reduce(function(a,b){return a+b;})/vals.length;\n  return avg>=1.5?'g':avg>=0.5?'a':'r';\n}\nfunction ragLabel(r){return '';}\nfunction ragTitle(r){return r==='exc'?'Exceeding (above 75th percentile)':r==='g'?'Strong (25th-75th percentile)':r==='a'?'Developing (5th-25th percentile)':r==='r2'?'Significantly below - 2 or more levels below year level':r==='r'?'Needs additional support (below 5th percentile)':r==='u'?'Unknown level - check source':'No data';}\nfunction ragBoxCls(r){if(r==='exc')return'flag-box flag-fill-exc';if(r==='r2')return'flag-box flag-fill-r2';if(r&&r!=='u')return'flag-box flag-fill-'+r;return r==='u'?'flag-box flag-box-u':'flag-box flag-box-n';}\n\n// Render a flag box cell\nfunction flagCell(rag,extraBorder,extraCls){\n  var bdr=extraBorder?'border-left:1px solid #BFDBFE;':'';\n  var fc=rag&&rag!=='u'?'flag-box flag-fill-'+rag:'flag-box flag-box-n';\n  var cls2=extraCls?' '+extraCls:'';\n  return'<td class=\"flag-cell'+cls2+'\" style=\"padding:0;'+bdr+'\" title=\"'+ragTitle(rag)+'\"><div class=\"'+fc+'\" style=\"min-height:33px;\">'+ragLabel(rag)+'</div></td>';\n}\nfunction flagCellNum(rag,extraBorder,extraCls){\n  var bdr=extraBorder?'border-left:1px solid #BBF7D0;':'';\n  var fc=rag&&rag!=='u'?'flag-box flag-fill-'+rag:'flag-box flag-box-n';\n  var cls2=extraCls?' '+extraCls:'';\n  return'<td class=\"flag-cell'+cls2+'\" style=\"padding:0;'+bdr+'\" title=\"'+ragTitle(rag)+'\"><div class=\"'+fc+'\" style=\"min-height:33px;\">'+ragLabel(rag)+'</div></td>';\n}\n\nfunction getR(s){\n  var gr=calcGrowth(s);\n  var pRA=rPAT(s.patr.a,'patr',s.yr);\n  var nRA=rNR(s.nr.a,s.yr);\n  var nWA=rNW(s.nw?s.nw.a:null);\n  var eTA=rTJ(s.etj.a,s.yr,'etj');\n  var eTWA=rTJ(s.etjw?s.etjw.a:null,s.yr,'etjw');\n  var eTSLA=rTJ(s.etjsl?s.etjsl.a:null,s.yr,'etjsl');\n  var pMA=rPAT(s.patm.a,'patm',s.yr);\n  var nNA=rNN(s.nn.a,s.yr);\n  var mTA=rTJ(s.mtj.a,s.yr,'mtj');\n  var pRG=rGrowth(gr.patr.g,gr.patr.exp,false);\n  var nRG=rGrowth(gr.nr.g,gr.nr.exp,true);\n  var nWG=rGrowth(gr.nw?gr.nw.g:null,null,false);\n  var eTG=rGrowthTJ(gr.etj.g);\n  var pMG=rGrowth(gr.patm.g,gr.patm.exp,false);\n  var nNG=rGrowth(gr.nn.g,gr.nn.exp,true);\n  var mTG=rGrowthTJ(gr.mtj.g);\n  return{\n    pRA:pRA,  pRG:pRG,  pRgr:gr.patr,\n    nRA:nRA,  nRG:nRG,  nRgr:gr.nr,\n    nWA:nWA,  nWG:nWG,\n    eTA:eTA,  eTG:eTG,  eTgr:gr.etj,\n    eTWA:eTWA, eTSLA:eTSLA,\n    pMA:pMA,  pMG:pMG,  pMgr:gr.patm,\n    nNA:nNA,  nNG:nNG,  nNgr:gr.nn,\n    mTA:mTA,  mTG:mTG,  mTgr:gr.mtj,\n    litAF: avgRAG([pRA,nRA,nWA,eTA,eTWA,eTSLA]),\n    litGF: avgRAG([pRG,nRG,nWG,eTG]),\n    numAF: avgRAG([pMA,nNA,mTA]),\n    numGF: avgRAG([pMG,nNG,mTG]),\n  };\n}\n\n// =====================================================================\n// SETTINGS PERSISTENCE\n// =====================================================================\nfunction loadSettings(){\n  try{var s=localStorage.getItem('lnd_settings2');if(s){var p=JSON.parse(s);T=p.T||T;schoolName=p.sn||schoolName;dashYear=p.dy||dashYear;}\n  }catch(e){}\n  // Privacy: student data is never stored in the browser; clear any old copy.\n  try{localStorage.removeItem('lnd_students2');}catch(e){}\n  updateHeader();\n  document.getElementById('setName').value=schoolName;\n  document.getElementById('setYear').value=dashYear;\n  loadTInputs();\n}\nfunction persist(){\n  // Persists settings/thresholds only. STUDENTS is never written to localStorage.\n  try{localStorage.setItem('lnd_settings2',JSON.stringify({T:T,sn:schoolName,dy:dashYear}));}catch(e){}\n}\nfunction updateHeader(){\n  document.getElementById('hdr-title').textContent=schoolName+' \\u2014 Literacy & Numeracy Dashboard';\n  document.getElementById('hdr-sub').textContent=dashYear;\n}\nfunction saveSchoolInfo(){\n  schoolName=document.getElementById('setName').value.trim()||'My School';\n  dashYear=document.getElementById('setYear').value.trim()||'2025';\n  updateHeader();persist();toast('School info saved');\n}\n\nfunction loadTInputs(){\n  function sv(id,v){var el=document.getElementById(id);if(el)el.value=v;}\n  [7,8,9,10].forEach(function(y){\n    sv('t_patr_'+y+'g',(T.patr[y]||T.patr[7]).g);\n    sv('t_patr_'+y+'a',(T.patr[y]||T.patr[7]).a);\n    sv('t_patm_'+y+'g',(T.patm[y]||T.patm[7]).g);\n    sv('t_patm_'+y+'a',(T.patm[y]||T.patm[7]).a);\n  });\n  sv('t_nr3_g',T.nr[3].g);sv('t_nr3_a',T.nr[3].a);\n  sv('t_nr5_g',T.nr[5].g);sv('t_nr5_a',T.nr[5].a);\n  sv('t_nr7_g',T.nr[7].g);sv('t_nr7_a',T.nr[7].a);\n  sv('t_nn3_g',T.nn[3].g);sv('t_nn3_a',T.nn[3].a);\n  sv('t_nn5_g',T.nn[5].g);sv('t_nn5_a',T.nn[5].a);\n  sv('t_nn7_g',T.nn[7].g);sv('t_nn7_a',T.nn[7].a);\n  sv('t_etj3',T.etj[3]);sv('t_etj4',T.etj[4]);sv('t_etj5',T.etj[5]);sv('t_etj6',T.etj[6]);sv('t_etj7',T.etj[7]||7);sv('t_etj8',T.etj[8]||8);sv('t_etj9',T.etj[9]||9);sv('t_etj10',T.etj[10]||10);\n  sv('t_mtj3',T.mtj[3]);sv('t_mtj4',T.mtj[4]);sv('t_mtj5',T.mtj[5]);sv('t_mtj6',T.mtj[6]);sv('t_mtj7',T.mtj[7]||7);sv('t_mtj8',T.mtj[8]||8);sv('t_mtj9',T.mtj[9]||9);sv('t_mtj10',T.mtj[10]||10);\n  sv('t_patr_exp_g',T.patr_gr.exp);sv('t_patr_exp_tol',T.patr_gr.tol);\n  sv('t_patm_exp_g',T.patm_gr.exp);sv('t_patm_exp_tol',T.patm_gr.tol);\n  sv('t_nr_35_exp',T.nr_gr['35'].exp);sv('t_nr_35_tol',T.nr_gr['35'].tol);\n  sv('t_nr_57_exp',T.nr_gr['57'].exp);sv('t_nr_57_tol',T.nr_gr['57'].tol);\n  sv('t_nn_35_exp',T.nn_gr['35'].exp);sv('t_nn_35_tol',T.nn_gr['35'].tol);\n  sv('t_nn_57_exp',T.nn_gr['57'].exp);sv('t_nn_57_tol',T.nn_gr['57'].tol);\n  sv('t_etj_exp_g',T.etj_gr.exp);sv('t_etj_exp_tol',T.etj_gr.tol);\n  sv('t_mtj_exp_g',T.mtj_gr.exp);sv('t_mtj_exp_tol',T.mtj_gr.tol);\n}\n\nfunction saveThresholds(){\n  function n(id){return parseFloat(document.getElementById(id).value)||0;}\n  T.patr={};T.patm={};\n  [7,8,9,10].forEach(function(y){\n    T.patr[y]={g:n('t_patr_'+y+'g'),a:n('t_patr_'+y+'a')};\n    T.patm[y]={g:n('t_patm_'+y+'g'),a:n('t_patm_'+y+'a')};\n  });\n  T.nr[3]={g:n('t_nr3_g'),a:n('t_nr3_a')};T.nr[5]={g:n('t_nr5_g'),a:n('t_nr5_a')};T.nr[7]={g:n('t_nr7_g'),a:n('t_nr7_a')};\n  T.nn[3]={g:n('t_nn3_g'),a:n('t_nn3_a')};T.nn[5]={g:n('t_nn5_g'),a:n('t_nn5_a')};T.nn[7]={g:n('t_nn7_g'),a:n('t_nn7_a')};\n  T.etj={3:n('t_etj3'),4:n('t_etj4'),5:n('t_etj5'),6:n('t_etj6'),7:n('t_etj7')||7,8:n('t_etj8')||8,9:n('t_etj9')||9,10:n('t_etj10')||10};\n  T.mtj={3:n('t_mtj3'),4:n('t_mtj4'),5:n('t_mtj5'),6:n('t_mtj6'),7:n('t_mtj7')||7,8:n('t_mtj8')||8,9:n('t_mtj9')||9,10:n('t_mtj10')||10};\n  T.patr_gr={exp:n('t_patr_exp_g'),tol:n('t_patr_exp_tol')};\n  T.patm_gr={exp:n('t_patm_exp_g'),tol:n('t_patm_exp_tol')};\n  T.nr_gr={'35':{exp:n('t_nr_35_exp'),tol:n('t_nr_35_tol')},'57':{exp:n('t_nr_57_exp'),tol:n('t_nr_57_tol')}};\n  T.nn_gr={'35':{exp:n('t_nn_35_exp'),tol:n('t_nn_35_tol')},'57':{exp:n('t_nn_57_exp'),tol:n('t_nn_57_tol')}};\n  T.etj_gr={exp:n('t_etj_exp_g'),tol:n('t_etj_exp_tol')};\n  T.mtj_gr={exp:n('t_mtj_exp_g'),tol:n('t_mtj_exp_tol')};\n  persist();renderData();toast('Thresholds saved - dashboard updated');\n}\nfunction resetThresholds(){T=JSON.parse(JSON.stringify(DEFAULT_T));loadTInputs();persist();renderData();toast('Thresholds reset to defaults');}\n\n// =====================================================================\n// FILTER HELPERS\n// =====================================================================\nfunction getFiltered(schId,yrId,clsId,nmId){\n  var sch=document.getElementById(schId||'fSch').value;\n  var yr=document.getElementById(yrId||'fYr').value;\n  var cls=document.getElementById(clsId||'fCls').value;\n  var nm=(document.getElementById(nmId||'fNm').value||'').toLowerCase().trim();\n  var yrN=yr?parseInt(yr.replace('Year ','')):0;\n  return STUDENTS.filter(function(s){return(!sch||s.sch===sch)&&(!yrN||s.yr===yrN)&&(!cls||s.form===cls)&&(!nm||s.name.toLowerCase().indexOf(nm)>-1);});\n}\nfunction updateCls(){\n  var sch=document.getElementById('fSch').value;var yr=document.getElementById('fYr').value;\n  var yrN=yr?parseInt(yr.replace('Year ','')):0;\n  var f=STUDENTS.filter(function(s){return(!sch||s.sch===sch)&&(!yrN||s.yr===yrN);});\n  var cls=[...new Set(f.map(function(s){return s.form;}))].sort();\n  var fC=document.getElementById('fCls');var cur=fC.value;\n  fC.innerHTML='<option value=\"\">All classes</option>'+cls.map(function(c){return'<option'+(c===cur?' selected':'')+'>'+c+'</option>';}).join('');\n}\nfunction initFilters(){\n  var schs=[...new Set(STUDENTS.map(function(s){return s.sch;}))].sort();\n  var yrs=[...new Set(STUDENTS.map(function(s){return s.yr;}))].sort();\n  function populate(id,vals,prefix,cur){var el=document.getElementById(id);if(!el)return;el.innerHTML=prefix+vals.map(function(v){return'<option'+(v===cur?' selected':'')+'>'+v+'</option>';}).join('');}\n  var cS=document.getElementById('fSch').value,cY=document.getElementById('fYr').value;\n  document.getElementById('fSch').innerHTML='<option value=\"\">All schools</option>'+schs.map(function(s){return'<option'+(s===cS?' selected':'')+'>'+s+'</option>';}).join('');\n  document.getElementById('fYr').innerHTML='<option value=\"\">All year levels</option>'+yrs.map(function(y){return'<option'+('Year '+y===cY?' selected':'')+'>Year '+y+'</option>';}).join('');\n  document.getElementById('chartYr').innerHTML='<option value=\"\">All year levels</option>'+yrs.map(function(y){return'<option>Year '+y+'</option>';}).join('');\n  document.getElementById('chartSch').innerHTML='<option value=\"\">All schools</option>'+schs.map(function(s){return'<option>'+s+'</option>';}).join('');\n  // Growth tab filters\n  var gSchEl=document.getElementById('gSch');var gYrEl=document.getElementById('gYr');var gClsEl=document.getElementById('gCls');\n  if(gSchEl)gSchEl.innerHTML='<option value=\"\">All schools</option>'+schs.map(function(s){return'<option>'+s+'</option>';}).join('');\n  if(gYrEl)gYrEl.innerHTML='<option value=\"\">All year levels</option>'+yrs.map(function(y){return'<option>Year '+y+'</option>';}).join('');\n  if(gClsEl){var allCls=[...new Set(STUDENTS.map(function(s){return s.form;}))].sort();gClsEl.innerHTML='<option value=\"\">All classes</option>'+allCls.map(function(c){return'<option>'+c+'</option>';}).join('');}\n  updateCls();\n}\n\n// =====================================================================\n// DATA VIEW RENDER\n// =====================================================================\nvar B2='border-left:2px solid #E2E8F0;';var B1='border-left:1px solid #F1F5F9;';\nvar selId=null;\n\nfunction ac(v,cls,bl,showText){\n  if(v===null||v===undefined||!cls){\n    return'<td class=\"t-ach\" style=\"'+(bl||'')+'\"><span class=\"t-na\">—</span></td>';\n  }\n  var tipText=String(v);\n  if(cls==='u')tipText='Unknown level - check source';\n  var label=showText?abbrevNAPLAN(v):'';\n  return'<td class=\"t-ach\" style=\"padding:0;'+(bl||'')+'\"><div class=\"rc rc-'+cls+'\" title=\"'+tipText+'\">'+label+'</div></td>';\n}\nfunction gc(gInfo,cls,bl,isNaplan){\n  var v=gInfo?gInfo.g:null;\n  if(v===null||v===undefined)return'<td class=\"t-grow\" style=\"'+(bl||'')+'\"><span class=\"t-na\">\\u2014</span></td>';\n  var arr=v>0?'\\u25b2':v<0?'\\u25bc':'\\u2014';\n  var lbl=v>0?'+'+v:v===0?'+-0':''+v;\n  var calc=gInfo&&gInfo.hasPrev?' &diams;':'';\n  var gwCls=cls||'gw-'+rGrowth(v,gInfo?gInfo.exp:null,isNaplan);\n  return'<td class=\"t-grow\" style=\"'+(bl||'')+'\"><span class=\"'+gwCls+'\">'+arr+'<span class=\"gw-num\">'+lbl+calc+'</span></span></td>';\n}\n\nfunction buildRow(s){\n  var r;try{r=getR(s);}catch(e){console.warn(\"buildRow err\",s.name,e);return'<tr><td colspan=\"11\" style=\"color:#94A3B8;padding:6px 10px;font-size:11px;\">'+s.name+' - data error</td></tr>';}\n  if(!r)return'';\n  return'<tr class=\"srow'+(selId===s.id?' sel':'')+'\" onclick=\"selStu('+s.id+')\" data-id=\"'+s.id+'\">'+\n    '<td class=\"t-name\">'+s.name+'</td>'+\n    '<td class=\"t-form\">'+s.form+'</td>'+\n    ac(s.patr.a,r.pRA,B2)+gc(r.pRgr,r.pRG?'gw-'+r.pRG:null,'')+\n    ac(s.nr.a,r.nRA,B1)+gc(r.nRgr,r.nRG?'gw-'+r.nRG:null,'',true)+\n    ac(s.nw?s.nw.a:null,r.nWA,B1)+'<td class=\"t-grow\" style=\"'+B1+'\"><span class=\"t-na\">\\u2014</span></td>'+\n    ac(s.etj.a,r.eTA,B1,true)+\n    ac(s.etjw?s.etjw.a:null,r.eTWA,B1,true)+\n    ac(s.etjsl?s.etjsl.a:null,r.eTSLA,B1,true)+gc(r.eTgr,r.eTG?'gw-'+r.eTG:null,'')+\n    ac(s.patm.a,r.pMA,B2)+gc(r.pMgr,r.pMG?'gw-'+r.pMG:null,'')+\n    ac(s.nn.a,r.nNA,B1)+gc(r.nNgr,r.nNG?'gw-'+r.nNG:null,'',true)+\n    ac(s.mtj.a,r.mTA,B1,true)+gc(r.mTgr,r.mTG?'gw-'+r.mTG:null,'')+\n  '</tr>';\n}\n\nfunction renderCards(data){\n  var c=document.getElementById('cards');if(!c||!data.length){if(c)c.innerHTML='';return;}\n  var hasPrev=data.filter(function(s){return s.prev&&(s.prev.patr||s.prev.patm);}).length;\n  var atG=data.filter(function(s){var pr=rPAT(s.patr.a,'patr',s.yr),pm=rPAT(s.patm.a,'patm',s.yr);return(pr==='g'||pr==='exc')&&(pm==='g'||pm==='exc');}).length;\n  var atR=data.filter(function(s){return rPAT(s.patr.a,'patr',s.yr)==='r'||rPAT(s.patm.a,'patm',s.yr)==='r';}).length;\n  function mc(lbl,val,sub){return'<div class=\"metric-card\"><div class=\"lbl\">'+lbl+'</div><div class=\"val\">'+(val!==null&&val!==undefined?val:'&mdash;')+'</div>'+(sub?'<div class=\"sub\">'+sub+'</div>':'')+'</div>';}\n  c.innerHTML=\n    mc('Students',data.length)+\n    '<div class=\"metric-card\"><div class=\"lbl\">Strong/Exc both PAT</div><div style=\"margin-top:4px;\"><span class=\"rag-g\" style=\"padding:2px 6px;\">'+atG+'</span><span class=\"sub\"> of '+data.length+'</span></div></div>'+\n    '<div class=\"metric-card\"><div class=\"lbl\">NAS in either PAT</div><div style=\"margin-top:4px;\"><span class=\"rag-r\" style=\"padding:2px 6px;\">'+atR+'</span><span class=\"sub\"> of '+data.length+'</span></div></div>'+\n    mc('With prev data',hasPrev,'of '+data.length);\n}\n\nfunction ragRank(r){return r==='exc'?4:r==='g'?3:r==='a'?2:r==='r'?1:0;}\nfunction ragMin(a,b){if(!a)return b;if(!b)return a;return ragRank(a)<=ragRank(b)?a:b;}\nfunction ragMax(a,b){if(!a)return b;if(!b)return a;return ragRank(a)>=ragRank(b)?a:b;}\n\nfunction updateColStats(data){\n  function fill(id,items,strFn,nasFn){\n    var el=document.getElementById(id);if(!el)return;\n    var has=items.filter(function(x){return x!==null;});\n    if(!has.length){el.innerHTML='<div class=\"cs-none\">-</div>';return;}\n    var str=has.filter(strFn).length,nas=has.filter(nasFn).length,tot=has.length;\n    el.innerHTML='<div class=\"cs-wrap\">'+\n      '<div class=\"cs-str\"><span class=\"sp\">'+Math.round(str/tot*100)+'%</span><span class=\"sl\">STRONG+</span></div>'+\n      '<div class=\"cs-nas\"><span class=\"sp\">'+Math.round(nas/tot*100)+'%</span><span class=\"sl\">NAS</span></div>'+\n      '</div>';\n  }\n  function isStrNas(r){return{str:r==='exc'||r==='g',nas:r==='r'||r==='r2'};}\n  fill('st-patr',data.map(function(s){return s.patr.a!==null?s:null;}),\n    function(s){return s&&(rPAT(s.patr.a,'patr',s.yr)==='exc'||rPAT(s.patr.a,'patr',s.yr)==='g');},\n    function(s){return s&&rPAT(s.patr.a,'patr',s.yr)==='r';});\n  fill('st-patm',data.map(function(s){return s.patm.a!==null?s:null;}),\n    function(s){return s&&(rPAT(s.patm.a,'patm',s.yr)==='exc'||rPAT(s.patm.a,'patm',s.yr)==='g');},\n    function(s){return s&&rPAT(s.patm.a,'patm',s.yr)==='r';});\n  function naplanBand(v,good){var l=String(v||'').toLowerCase();return good?l==='exceeding'||l==='strong':l==='needs additional support';}\n  fill('st-nr', data.map(function(s){return s.nr&&s.nr.a?s:null;}),\n    function(s){return s&&naplanBand(s.nr.a,true);},function(s){return s&&naplanBand(s.nr.a,false);});\n  fill('st-nw', data.map(function(s){return s.nw&&s.nw.a?s:null;}),\n    function(s){return s&&naplanBand(s.nw.a,true);},function(s){return s&&naplanBand(s.nw.a,false);});\n  fill('st-nn', data.map(function(s){return s.nn&&s.nn.a?s:null;}),\n    function(s){return s&&naplanBand(s.nn.a,true);},function(s){return s&&naplanBand(s.nn.a,false);});\n  function tjBand(s,fld){var v=s[fld]&&s[fld].a;if(!v)return null;return rTJ(v,s.yr,fld);}\n  fill('st-etj', data.map(function(s){return s.etj&&s.etj.a?s:null;}),\n    function(s){var r=s&&tjBand(s,'etj');return r==='exc'||r==='g';},\n    function(s){var r=s&&tjBand(s,'etj');return r==='r'||r==='r2';});\n  fill('st-etjw',data.map(function(s){return s.etjw&&s.etjw.a?s:null;}),\n    function(s){var r=s&&tjBand(s,'etjw');return r==='exc'||r==='g';},\n    function(s){var r=s&&tjBand(s,'etjw');return r==='r'||r==='r2';});\n  fill('st-etjsl',data.map(function(s){return s.etjsl&&s.etjsl.a?s:null;}),\n    function(s){var r=s&&tjBand(s,'etjsl');return r==='exc'||r==='g';},\n    function(s){var r=s&&tjBand(s,'etjsl');return r==='r'||r==='r2';});\n  fill('st-mtj', data.map(function(s){return s.mtj&&s.mtj.a?s:null;}),\n    function(s){var r=s&&tjBand(s,'mtj');return r==='exc'||r==='g';},\n    function(s){var r=s&&tjBand(s,'mtj');return r==='r'||r==='r2';});\n}\nfunction renderData(){\n  var data=getFiltered();\n  var body=document.getElementById('tbody');var cnt=document.getElementById('rowCount');\n  renderCards(data);\n  if(!data.length){body.innerHTML='<tr><td colspan=\"11\" style=\"text-align:center;padding:2.5rem;color:#CBD5E1;font-size:13px;\">No students match the current filters</td></tr>';cnt.textContent='';if(selId){selId=null;document.getElementById('dpanel').style.display='none';}updateColStats(data);return;}\n  body.innerHTML=data.map(buildRow).join('');\n  cnt.textContent=data.length+' student'+(data.length!==1?'s':'')+' shown';\nupdateColStats(data);\n}\n\n// =====================================================================\n// STUDENT DETAIL PANEL\n// =====================================================================\nfunction selStu(id){\n  var panel=document.getElementById('dpanel');\n  if(selId===id){selId=null;panel.style.display='none';renderData();return;}\n  selId=id;renderData();\n  var s=STUDENTS.find(function(x){return x.id===id;});\n  var r=getR(s);var gr=calcGrowth(s);\n  var ini=s.name.split(' ').map(function(n){return n[0];}).join('');\n  var p=s.prev||{};\n\n  function detRow(lbl,cur,curCls,prevVal,gInfo,isNaplan){\n    var curH=cur!==null&&cur!==undefined?'<span class=\"rag-'+(curCls||'a')+'\">'+cur+'</span>':'<span style=\"color:#CBD5E1;font-size:12px;\">\\u2014</span>';\n    var prevH=prevVal!==null&&prevVal!==undefined?'<span class=\"rag-b\">'+prevVal+'</span>':'<span style=\"color:#CBD5E1;font-size:12px;\">\\u2014</span>';\n    var gv=gInfo?gInfo.g:null;var gc2='\\u2014';\n    if(gv!==null){\n      var rc=rGrowth(gv,gInfo.exp,isNaplan);\n      var arr=gv>0?'\\u25b2':gv<0?'\\u25bc':'\\u2014';\n      gc2='<span class=\"gw-'+rc+'\">'+arr+' '+(gv>0?'+':'')+gv+(gInfo.hasPrev?' &#128312;':'')+' </span>';\n      if(gInfo.exp){var expLine=' <span style=\"font-size:10px;color:#94A3B8;\">(exp: '+(isNaplan?gInfo.exp.exp:gInfo.exp.exp)+')</span>';gc2+=expLine;}\n    }\n    return'<tr><td>'+lbl+'</td><td style=\"padding-left:10px;\">'+curH+'</td><td style=\"padding-left:10px;\">'+prevH+'</td><td style=\"padding-left:10px;\">'+gc2+'</td></tr>';\n  }\n\n  var naplPrevLabel=p.naplan_yr?'Yr '+p.naplan_yr+(p.naplan_testyear?' ('+p.naplan_testyear+')':''):'\\u2014';\n\n  panel.innerHTML=\n    '<div class=\"detail-hdr\">'+\n      '<div style=\"display:flex;align-items:center;gap:12px;\">'+\n        '<div class=\"avatar\">'+ini+'</div>'+\n        '<div><div style=\"font-size:15px;font-weight:600;color:#0F172A;\">'+s.name+'</div>'+\n        '<div style=\"font-size:12px;color:#94A3B8;margin-top:2px;\">'+s.form+' &middot; Year '+s.yr+' &middot; '+s.sch+(p.naplan_yr?' &middot; NAPLAN prev: '+naplPrevLabel:'')+'</div></div>'+\n      '</div>'+\n      '<div style=\"display:flex;gap:8px;\"><button class=\"btn btn-sm\" onclick=\"editStudent('+s.id+')\">Edit</button><button class=\"btn btn-sm btn-danger\" onclick=\"deleteStudent('+s.id+')\">Remove</button></div>'+\n    '</div>'+\n    '<div class=\"detail-grid\">'+\n      '<div>'+\n        '<div class=\"dom-lbl lit\">LITERACY</div>'+\n        '<table class=\"dt\"><thead><tr>'+\n          '<th style=\"font-size:11px;font-weight:500;color:#CBD5E1;text-align:left;padding-bottom:8px;\">Assessment</th>'+\n          '<th style=\"font-size:11px;font-weight:500;color:#CBD5E1;padding-bottom:8px;padding-left:10px;\">Current</th>'+\n          '<th style=\"font-size:11px;font-weight:500;color:#7C3AED;padding-bottom:8px;padding-left:10px;\">Previous</th>'+\n          '<th style=\"font-size:11px;font-weight:500;color:#CBD5E1;padding-bottom:8px;padding-left:10px;\">Growth</th>'+\n        '</tr></thead><tbody>'+\n          detRow('PAT-R',s.patr.a,r.pRA,p.patr,gr.patr,false)+\n          detRow('NAPLAN Reading',s.nr.a,r.nRA,p.nr,gr.nr,true)+\n          detRow('English TJ',s.etj.a,r.eTA,p.etj,gr.etj,false)+\n        '</tbody></table>'+\n      '</div>'+\n      '<div>'+\n        '<div class=\"dom-lbl num\">NUMERACY</div>'+\n        '<table class=\"dt\"><thead><tr>'+\n          '<th style=\"font-size:11px;font-weight:500;color:#CBD5E1;text-align:left;padding-bottom:8px;\">Assessment</th>'+\n          '<th style=\"font-size:11px;font-weight:500;color:#CBD5E1;padding-bottom:8px;padding-left:10px;\">Current</th>'+\n          '<th style=\"font-size:11px;font-weight:500;color:#7C3AED;padding-bottom:8px;padding-left:10px;\">Previous</th>'+\n          '<th style=\"font-size:11px;font-weight:500;color:#CBD5E1;padding-bottom:8px;padding-left:10px;\">Growth</th>'+\n        '</tr></thead><tbody>'+\n          detRow('PAT-M',s.patm.a,r.pMA,p.patm,gr.patm,false)+\n          detRow('NAPLAN Numeracy',s.nn.a,r.nNA,p.nn,gr.nn,true)+\n          detRow('Maths TJ',s.mtj.a,r.mTA,p.mtj,gr.mtj,false)+\n        '</tbody></table>'+\n      '</div>'+\n    '</div>';\n\n  panel.style.display='block';\n  setTimeout(function(){panel.scrollIntoView({behavior:'smooth',block:'nearest'});},60);\n}\n\nfunction deleteStudent(id){\n  if(!confirm('Remove this student?'))return;\n  STUDENTS=STUDENTS.filter(function(s){return s.id!==id;});\n  persist();selId=null;document.getElementById('dpanel').style.display='none';\n  initFilters();renderData();toast('Student removed');\n}\n\n// =====================================================================\n// GROWTH TAB\n// ================// =====================================================================\n// GROWTH TAB\n// =====================================================================\nvar gCharts={};\n\nfunction getGrowthFiltered(){\n  var sch=document.getElementById('gSch').value;\n  var yr=document.getElementById('gYr').value;\n  var cls=document.getElementById('gCls').value;\n  var yrN=yr?parseInt(yr.replace('Year ','')):0;\n  return STUDENTS.filter(function(s){return(!sch||s.sch===sch)&&(!yrN||s.yr===yrN)&&(!cls||s.form===cls);});\n}\n\nfunction renderGrowth(){\n  var domain=document.getElementById('gDomain').value;\n  var data=getGrowthFiltered();\n  var domainList=domain==='all'?['patr','nr','etj','patm','nn','mtj']:[domain];\n  var domainLabels={patr:'PAT-R',nr:'NAPLAN Reading',etj:'English TJ',patm:'PAT-M',nn:'NAPLAN Numeracy',mtj:'Maths TJ'};\n  var domainIsNaplan={patr:false,nr:true,etj:false,patm:false,nn:true,mtj:false};\n\n  function countRag(domain2){\n    var g=0,a=0,r=0,n=0;\n    data.forEach(function(s){\n      var gr=calcGrowth(s);var d=gr[domain2];if(d.g===null){n++;return;}\n      var rc=rGrowth(d.g,d.exp,domainIsNaplan[domain2]);\n      if(rc==='g')g++;else if(rc==='a')a++;else r++;\n    });\n    return{g:g,a:a,r:r,n:n};\n  }\n\n  var firstDomain=domainList[0];var rc0=countRag(firstDomain);\n  var withPrev=data.filter(function(s){var gr=calcGrowth(s);return gr[firstDomain].hasPrev;}).length;\n  var gcards=document.getElementById('growth-cards');\n  gcards.innerHTML=\n    '<div class=\"metric-card\"><div class=\"lbl\">Students</div><div class=\"val\">'+data.length+'</div></div>'+\n    '<div class=\"metric-card\"><div class=\"lbl\">With previous data</div><div style=\"margin-top:6px;\"><span class=\"rag-b\">'+withPrev+'</span><span class=\"sub\"> of '+data.length+'</span></div></div>'+\n    '<div class=\"metric-card\"><div class=\"lbl\">Above expected growth</div><div style=\"margin-top:6px;\"><span class=\"rag-g\">'+rc0.g+'</span></div></div>'+\n    '<div class=\"metric-card\"><div class=\"lbl\">Meeting expected growth</div><div style=\"margin-top:6px;\"><span class=\"rag-a\">'+rc0.a+'</span></div></div>'+\n    '<div class=\"metric-card\"><div class=\"lbl\">Below expected growth</div><div style=\"margin-top:6px;\"><span class=\"rag-r\">'+rc0.r+'</span></div></div>';\n\n  var summRows=domainList.map(function(d){\n    var rc=countRag(d);var total=rc.g+rc.a+rc.r;\n    var pctG=total?Math.round(rc.g/total*100):0;\n    var pctA=total?Math.round(rc.a/total*100):0;\n    var pctR=total?Math.round(rc.r/total*100):0;\n    var isN=domainIsNaplan[d];\n    var expLabel=isN?(T.nr_gr['35']?'Yr3\\u21925: +'+T.nr_gr['35'].exp:'\\u2014'):'exp: +'+(d==='patr'?T.patr_gr.exp:d==='patm'?T.patm_gr.exp:d==='etj'?T.etj_gr.exp:T.mtj_gr.exp);\n    return'<tr>'+\n      '<td style=\"font-weight:500;\">'+domainLabels[d]+'</td>'+\n      '<td style=\"color:#94A3B8;font-size:11px;\">'+expLabel+'</td>'+\n      '<td><span class=\"rag-g\">'+rc.g+'</span></td>'+\n      '<td><span class=\"rag-a\">'+rc.a+'</span></td>'+\n      '<td><span class=\"rag-r\">'+rc.r+'</span></td>'+\n      '<td><span class=\"rag-b\">'+rc.n+'</span></td>'+\n      '<td><div style=\"display:flex;height:6px;border-radius:99px;overflow:hidden;background:#F1F5F9;min-width:80px;\">'+\n        '<div style=\"width:'+pctG+'%;background:#86EFAC;\"></div>'+\n        '<div style=\"width:'+pctA+'%;background:#FDE68A;\"></div>'+\n        '<div style=\"width:'+pctR+'%;background:#FCA5A5;\"></div>'+\n      '</div></td></tr>';\n  }).join('');\n\n  document.getElementById('growth-summary').innerHTML=\n    '<table><thead><tr>'+\n    '<th>Domain</th><th>Expected</th><th><span class=\"rag-exc\" style=\"font-size:10px;\">Exc</span></th><th><span class=\"rag-g\" style=\"font-size:10px;\">Str</span></th><th><span class=\"rag-a\" style=\"font-size:10px;\">Dev</span></th><th><span class=\"rag-r\" style=\"font-size:10px;\">NAS</span></th><th><span class=\"rag-b\" style=\"font-size:10px;\">No data</span></th><th style=\"min-width:100px;\">Distribution</th></tr></thead><tbody>'+summRows+'</tbody></table>';\n\n  var chartDoms=domain==='all'?domainList:domainList.slice(0,1);\n  var gc2=document.getElementById('growth-charts');\n  gc2.innerHTML='';\n  Object.keys(gCharts).forEach(function(k){if(gCharts[k]){gCharts[k].destroy();}});\n  gCharts={};\n\n  chartDoms.forEach(function(d){\n    var isN=domainIsNaplan[d];\n    var sd=data.filter(function(s){return calcGrowth(s)[d].hasPrev;});\n    if(!sd.length)return;\n    var labels=sd.map(function(s){return s.name.split(' ')[0];});\n    var actuals=sd.map(function(s){return calcGrowth(s)[d].g;});\n    var expGr=sd.map(function(s){var e=calcGrowth(s)[d].exp;return e?e.exp:null;})[0];\n    var colors=sd.map(function(s){var rc=rGrowth(calcGrowth(s)[d].g,calcGrowth(s)[d].exp,isN);return rc==='g'?'#86EFAC':rc==='a'?'#FDE68A':'#FCA5A5';});\n    var canvId='gc_'+d;\n    gc2.insertAdjacentHTML('beforeend','<div class=\"growth-card\"><div class=\"growth-card-title\">'+domainLabels[d]+'</div><div class=\"growth-card-sub\">Actual growth per student'+(expGr!==null?' \\u2014 expected: +'+expGr:'')+'</div><div class=\"chart-wrap\"><canvas id=\"'+canvId+'\" role=\"img\"></canvas></div></div>');\n    var datasets=[{type:'bar',data:actuals,backgroundColor:colors,borderWidth:0,borderRadius:3}];\n    if(expGr!==null)datasets.push({type:'line',data:Array(labels.length).fill(expGr),borderColor:'#475569',borderDash:[5,4],borderWidth:1.5,pointRadius:0,fill:false,label:'Expected'});\n    gCharts[d]=new Chart(document.getElementById(canvId),{\n      type:'bar',data:{labels:labels,datasets:datasets},\n      options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:function(ctx){return ctx.dataset.label||(ctx.parsed.y>0?'+':'')+ctx.parsed.y;}}}},\n      scales:{y:{grid:{color:'#F8FAFC'},ticks:{font:{size:11},color:'#94A3B8'}},x:{grid:{display:false},ticks:{font:{size:11},color:'#475569'}}}}\n    });\n  });\n\n  var primaryDomain=domainList[0];\n  document.getElementById('gh1').textContent='Previous';\n  document.getElementById('gh2').textContent='Current';\n  document.getElementById('gh3').textContent='Growth';\n  document.getElementById('gh4').textContent='Expected';\n  document.getElementById('gh5').textContent='vs Expected';\n  document.getElementById('gh6').textContent='RAG';\n\n  var tbody='';var shown=0;\n  data.forEach(function(s){\n    var gr=calcGrowth(s);var d=gr[primaryDomain];\n    if(!d.hasPrev&&domain!=='all')return;\n    var fieldMap={patr:'patr',patm:'patm',nr:'nr',nn:'nn',etj:'etj',mtj:'mtj'};\n    var prev=s.prev?s.prev[fieldMap[primaryDomain]]:null;\n    var cur=primaryDomain==='patr'?s.patr.a:primaryDomain==='patm'?s.patm.a:primaryDomain==='nr'?s.nr.a:primaryDomain==='nn'?s.nn.a:primaryDomain==='etj'?s.etj.a:s.mtj.a;\n    var gv=d.g;var expV=d.exp?d.exp.exp:null;var tol=d.exp?d.exp.tol:null;\n    var vs=gv!==null&&expV!==null?Math.round((gv-expV)*10)/10:null;\n    var rc=rGrowth(gv,d.exp,domainIsNaplan[primaryDomain]);\n    tbody+='<tr class=\"srow\" onclick=\"selStu('+s.id+');showTab(\\'data\\',document.querySelectorAll(\\'.tab-btn\\')[0])\" style=\"border-bottom:1px solid #F8FAFC;\">'+\n      '<td class=\"t-name\">'+s.name+'</td>'+\n      '<td class=\"t-form\">'+s.form+'</td>'+\n      '<td style=\"text-align:center;padding:7px 8px;\">'+(prev!==null&&prev!==undefined?'<span class=\"rag-b\">'+prev+'</span>':'<span class=\"t-na\">\\u2014</span>')+'</td>'+\n      '<td style=\"text-align:center;padding:7px 8px;\">'+(cur!==null&&cur!==undefined?'<span class=\"rag-'+(primaryDomain.indexOf('pat')>-1?rPAT(cur,primaryDomain,s.yr):'b')+'\">'+cur+'</span>':'<span class=\"t-na\">\\u2014</span>')+'</td>'+\n      '<td style=\"text-align:center;padding:7px 8px;\">'+(gv!==null?'<span class=\"gw-'+(rc||'a')+'\">'+(gv>0?'\\u25b2 +':gv<0?'\\u25bc ':'\\u2014 ')+gv+'</span>':'<span class=\"t-na\">\\u2014</span>')+'</td>'+\n      '<td style=\"text-align:center;padding:7px 8px;color:#64748B;font-size:12px;\">'+(expV!==null?'+'+expV+(tol?' \\u00b1'+tol:''):'\\u2014')+'</td>'+\n      '<td style=\"text-align:center;padding:7px 8px;\">'+(vs!==null?'<span class=\"gw-'+rc+'\">'+(vs>0?'+':'')+vs+'</span>':'<span class=\"t-na\">\\u2014</span>')+'</td>'+\n      '<td style=\"text-align:center;padding:7px 8px;\">'+(rc?'<span class=\"rag-'+rc+'\">'+(rc==='g'?'Above':rc==='a'?'Meeting':'Below')+'</span>':'<span class=\"t-na\">\\u2014</span>')+'</td>'+\n    '</tr>';shown++;\n  });\n  if(!shown)tbody='<tr><td colspan=\"8\" style=\"text-align:center;padding:2rem;color:#CBD5E1;font-size:13px;\">No previous data available for this selection</td></tr>';\n  document.getElementById('growth-tbody').innerHTML=tbody;\n  document.getElementById('growth-count').textContent=shown+' student'+(shown!==1?'s':'')+' shown';\n}\n\n// =====================================================================\n// CHARTS TAB\n// =====================================================================\nvar CI={};\nfunction destroyChart(id){if(CI[id]){CI[id].destroy();delete CI[id];}}\nfunction mkChart(id,labels,vals,ragFn,greenTh,amberTh,yLbl,yMin){\n  destroyChart(id);\n  var n=labels.length;\n  var colors=vals.map(function(v){if(v===null)return'#E2E8F0';var r=ragFn(v);return r==='g'?'#86EFAC':r==='a'?'#FDE68A':'#FCA5A5';});\n  var borders=vals.map(function(v){if(v===null)return'#CBD5E1';var r=ragFn(v);return r==='g'?'#16A34A':r==='a'?'#D97706':'#DC2626';});\n  var datasets=[{type:'bar',label:'Class avg',data:vals,backgroundColor:colors,borderColor:borders,borderWidth:1.5,borderRadius:4}];\n  if(greenTh!=null){\n    datasets.push({type:'line',label:'Green threshold',data:Array(n).fill(greenTh),borderColor:'#16A34A',borderDash:[6,4],borderWidth:1.5,pointRadius:0,fill:false,tension:0});\n    datasets.push({type:'line',label:'Amber threshold',data:Array(n).fill(amberTh),borderColor:'#D97706',borderDash:[6,4],borderWidth:1.5,pointRadius:0,fill:false,tension:0});\n  }\n  CI[id]=new Chart(document.getElementById(id),{type:'bar',data:{labels:labels,datasets:datasets},\n    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:function(ctx){return(ctx.dataset.label||'')+(ctx.parsed.y!==null?': '+ctx.parsed.y:'');}}}},\n    scales:{y:{beginAtZero:false,min:yMin,grid:{color:'#F8FAFC'},ticks:{font:{size:11},color:'#94A3B8'},title:{display:true,text:yLbl,font:{size:11},color:'#94A3B8'}},x:{grid:{display:false},ticks:{font:{size:12},color:'#475569'}}}}\n  });\n}\nfunction renderCharts(){\n  var yr=document.getElementById('chartYr').value;var sch=document.getElementById('chartSch').value;\n  var yrN=yr?parseInt(yr.replace('Year ','')):0;\n  var fAchV=document.getElementById('fAch').value;\n  var fGrwV=document.getElementById('fGrw').value;\n  var data=STUDENTS.filter(function(s){\n    if(!(!yrN||s.yr===yrN)||!(!sch||s.sch===sch))return false;\n    if(nasMode){var r0=getR(s);if(r0.litAF!=='r'&&r0.numAF!=='r')return false;}\n    if(fAchV||fGrwV){\n      var rr=getR(s);\n      if(fAchV){\n        var wa=ragMin(rr.litAF,rr.numAF);\n        if(wa!==fAchV)return false;\n      }\n      if(fGrwV){\n        var wg=ragMin(rr.litGF,rr.numGF),bg=ragMax(rr.litGF,rr.numGF);\n        if(fGrwV==='high'&&bg!=='exc')return false;\n        if(fGrwV==='expected'&&(bg==='exc'||wg==='r'))return false;\n        if(fGrwV==='low'&&wg!=='r')return false;\n      }\n    }\n    return true;\n  });\n  var cls=[...new Set(data.map(function(s){return s.form;}))].sort();\n  function byClass(fn){return cls.map(function(c){var cd=data.filter(function(s){return s.form===c;});var v=cd.map(fn).filter(function(x){return x!==null&&x!==undefined;});return v.length?Math.round(v.reduce(function(a,b){return a+b;})/v.length*10)/10:null;});}\n  var avgYr=yrN||5;var nrT=T.nr[avgYr]||T.nr[5];var nnT=T.nn[avgYr]||T.nn[5];\n  var patrTh=PAT_THRESHOLDS.r[avgYr]||PAT_THRESHOLDS.r[8];var patmTh=PAT_THRESHOLDS.m[avgYr]||PAT_THRESHOLDS.m[8];\n  mkChart('cPATR',cls,byClass(function(s){return s.patr.a;}),function(v){return rPAT(v,'r',avgYr);},patrTh.exc,patrTh.str,'Scale score',50);\n  mkChart('cPATM',cls,byClass(function(s){return s.patm.a;}),function(v){return rPAT(v,'m',avgYr);},patmTh.exc,patmTh.str,'Scale score',50);\n  mkChart('cNR',cls,byClass(function(s){return s.nr.a;}),function(v){return rNR(v,avgYr);},nrT.g,nrT.a,'Score',200);\n  mkChart('cNN',cls,byClass(function(s){return s.nn.a;}),function(v){return rNN(v,avgYr);},nnT.g,nnT.a,'Score',200);\n  mkChart('cETJ',cls,byClass(function(s){return s.etj.a;}),function(v){return rTJ(v,avgYr,'etj');},T.etj[avgYr],T.etj[avgYr]-1,'VC Level',0);\n  mkChart('cMTJ',cls,byClass(function(s){return s.mtj.a;}),function(v){return rTJ(v,avgYr,'mtj');},T.mtj[avgYr],T.mtj[avgYr]-1,'VC Level',0);\n}\n\n// =====================================================================\n// MODAL\n// =====================================================================\nfunction switchModalTab(tab,btn){\n  document.querySelectorAll('.modal-tab').forEach(function(b){b.classList.remove('active');});\n  document.querySelectorAll('.modal-tab-panel').forEach(function(p){p.classList.remove('active');});\n  btn.classList.add('active');document.getElementById('mtab-'+tab).classList.add('active');\n}\nfunction openModal(s){\n  document.getElementById('modal-title').textContent=s?'Edit student':'Add student';\n  document.getElementById('modal-id').value=s?s.id:'';\n  function sv(id,v){var el=document.getElementById(id);if(el)el.value=(v!==null&&v!==undefined)?v:'';}\n  var p=s&&s.prev?s.prev:{};\n  if(s){\n    sv('m_name',s.name);sv('m_form',s.form);document.getElementById('m_yr').value=s.yr;sv('m_sch',s.sch);\n    sv('m_patr_a',s.patr.a);sv('m_patr_g',s.patr.g||'');sv('m_nr_a',s.nr.a);sv('m_nr_g',s.nr.g||'');\n    sv('m_etj_a',s.etj.a);sv('m_etj_g',s.etj.g||'');sv('m_patm_a',s.patm.a);sv('m_patm_g',s.patm.g||'');\n    sv('m_nn_a',s.nn.a);sv('m_nn_g',s.nn.g||'');sv('m_mtj_a',s.mtj.a);sv('m_mtj_g',s.mtj.g||'');\n    sv('m_naplan_prev_yr',p.naplan_yr||'');sv('m_naplan_prev_testyear',p.naplan_testyear||'');\n    sv('m_prev_nr',p.nr);sv('m_prev_nn',p.nn);sv('m_prev_patr',p.patr);sv('m_prev_patm',p.patm);\n    sv('m_prev_etj',p.etj);sv('m_prev_mtj',p.mtj);\n  } else {\n    ['m_name','m_form','m_sch','m_patr_a','m_patr_g','m_nr_a','m_nr_g','m_etj_a','m_etj_g',\n     'm_patm_a','m_patm_g','m_nn_a','m_nn_g','m_mtj_a','m_mtj_g',\n     'm_nw_a','m_nw_g','m_naplan_prev_yr','m_naplan_prev_testyear','m_prev_nr','m_prev_nn','m_prev_patr','m_prev_patm','m_prev_etj','m_prev_mtj'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';}); \n  }\n  document.querySelectorAll('.modal-tab').forEach(function(b){b.classList.remove('active');});\n  document.querySelectorAll('.modal-tab-panel').forEach(function(p2){p2.classList.remove('active');});\n  document.querySelectorAll('.modal-tab')[0].classList.add('active');\n  document.getElementById('mtab-current').classList.add('active');\n  document.getElementById('modal-overlay').classList.add('open');\n  setTimeout(function(){document.getElementById('m_name').focus();},100);\n}\nfunction editStudent(id){var s=STUDENTS.find(function(x){return x.id===id;});if(s)openModal(s);}\nfunction closeModal(){document.getElementById('modal-overlay').classList.remove('open');}\nfunction saveStudent(){\n  var name=document.getElementById('m_name').value.trim();\n  if(!name){alert('Please enter a student name.');return;}\n  function nv(id){var v=document.getElementById(id).value;return(v===''||v===null||isNaN(parseFloat(v)))?null:parseFloat(v);}\n  function iv(id){var v=document.getElementById(id).value;return(v===''||v===null)?null:parseInt(v);}\n  var stu={\n    name:name,form:document.getElementById('m_form').value.trim(),\n    yr:parseInt(document.getElementById('m_yr').value),sch:document.getElementById('m_sch').value.trim(),\n    patr:{a:nv('m_patr_a'),g:nv('m_patr_g')},nr:{a:nv('m_nr_a'),g:nv('m_nr_g')},\n    nw:{a:document.getElementById('m_nw_a')?document.getElementById('m_nw_a').value.trim()||null:null,g:nv('m_nw_g')},\n    etj:{a:nv('m_etj_a'),g:nv('m_etj_g')},patm:{a:nv('m_patm_a'),g:nv('m_patm_g')},\n    nn:{a:nv('m_nn_a'),g:nv('m_nn_g')},mtj:{a:nv('m_mtj_a'),g:nv('m_mtj_g')},\n    prev:{patr:nv('m_prev_patr'),patm:nv('m_prev_patm'),nr:nv('m_prev_nr'),nn:nv('m_prev_nn'),\n      etj:nv('m_prev_etj'),mtj:nv('m_prev_mtj'),naplan_yr:iv('m_naplan_prev_yr')||null,naplan_testyear:iv('m_naplan_prev_testyear')||null}\n  };\n  var eid=document.getElementById('modal-id').value;\n  if(eid){var idx=STUDENTS.findIndex(function(s){return s.id===parseInt(eid);});if(idx>-1){stu.id=parseInt(eid);STUDENTS[idx]=stu;}}\n  else{stu.id=Date.now();STUDENTS.push(stu);}\n  persist();closeModal();initFilters();renderData();\n  if(eid&&selId===parseInt(eid)){setTimeout(function(){selStu(parseInt(eid));},100);}\n  toast(eid?'Student updated':'Student added');\n}\ndocument.getElementById('modal-overlay').addEventListener('click',function(e){if(e.target===this)closeModal();});\n\n// =====================================================================\n// CSV MAPPER\n// =====================================================================\nvar CSV_HEADER='Name,Form,Year Level,School,PAT-R Ach,NAPLAN-R Ach,NAPLAN-W Ach,Eng TJ Ach,PAT-M Ach,NAPLAN-N Ach,Maths TJ Ach,Prev NAPLAN Yr Level,Prev NAPLAN Test Year,Prev NAPLAN Reading,Prev NAPLAN Numeracy,Prev PAT-R,Prev PAT-M,Prev Eng TJ,Prev Maths TJ';\n\nvar FIELDS=[\n  {key:'name',label:'Student name',req:true,type:'str',hint:'Required'},\n  {key:'form',label:'Form / class',req:false,type:'str',hint:'e.g. 5A'},\n  {key:'yr',label:'Year level',req:false,type:'int',hint:'e.g. 5'},\n  {key:'sch',label:'School / campus',req:false,type:'str',hint:'e.g. Riverside PS'},\n  {key:'patr_a',label:'PAT-R Achievement',req:false,type:'flt',hint:'Scale score',sec:'lit'},\n  {key:'nr_a',label:'NAPLAN Reading Ach',req:false,type:'flt',hint:'Score or label',sec:'lit'},\n  {key:'nw_a',label:'NAPLAN Writing Ach',req:false,type:'str',hint:'Score or label',sec:'lit'},\n  {key:'nw_g',label:'NAPLAN Writing Growth',req:false,type:'flt',hint:'Delta',sec:'lit'},\n  {key:'etj_a',label:'English TJ Achievement',req:false,type:'flt',hint:'VC Level',sec:'lit'},\n  {key:'patm_a',label:'PAT-M Achievement',req:false,type:'flt',hint:'Scale score',sec:'num'},\n  {key:'nn_a',label:'NAPLAN Numeracy Ach',req:false,type:'flt',hint:'Score',sec:'num'},\n  {key:'mtj_a',label:'Maths TJ Achievement',req:false,type:'flt',hint:'VC Level',sec:'num'},\n  {key:'naplan_prev_yr',label:'Prev NAPLAN year level',req:false,type:'int',hint:'e.g. 3',sec:'prev'},\n  {key:'naplan_testyear',label:'Prev NAPLAN test year',req:false,type:'int',hint:'e.g. 2023',sec:'prev'},\n  {key:'prev_nr',label:'Prev NAPLAN Reading score',req:false,type:'flt',hint:'Score 2 yrs ago',sec:'prev'},\n  {key:'prev_nn',label:'Prev NAPLAN Numeracy score',req:false,type:'flt',hint:'Score 2 yrs ago',sec:'prev'},\n  {key:'prev_patr',label:'Prev PAT-R score',req:false,type:'flt',hint:'Previous scale score',sec:'prev'},\n  {key:'prev_patm',label:'Prev PAT-M score',req:false,type:'flt',hint:'Previous scale score',sec:'prev'},\n  {key:'prev_etj',label:'Prev English TJ',req:false,type:'flt',hint:'Previous VC Level',sec:'prev'},\n  {key:'prev_mtj',label:'Prev Maths TJ',req:false,type:'flt',hint:'Previous VC Level',sec:'prev'},\n];\n\nvar KEYWORDS={\n  name:['student name','full name','legal name','name'],\n  form:['form class','homeroom','home room','form','class'],\n  yr:['year level','year group','year','grade'],\n  sch:['school name','campus','school','site'],\n  patr_a:['pat-r ach','pat-r score','pat-r scale','pat reading ach','patr ach','pat-r'],\n  nr_a:['naplan reading ach','naplan-r ach','naplan read ach','naplan reading score','naplan reading'],\n  etj_a:['english tj ach','english teacher','english vc','eng tj ach','etj ach','english tj','eng tj'],\n  patm_a:['pat-m ach','pat-m score','pat-m scale','pat maths ach','patm ach','pat-m'],\n  nn_a:['naplan numeracy ach','naplan-n ach','naplan num ach','naplan numeracy score','naplan numeracy'],\n  mtj_a:['maths tj ach','maths teacher','maths vc','mtj ach','maths tj','math tj'],\n  naplan_prev_yr:['prev naplan yr','prev naplan year level','previous naplan year','naplan prev year'],\n  naplan_testyear:['prev naplan test year','naplan test year','previous test year','naplan year tested'],\n  prev_nr:['prev naplan reading','previous naplan reading','naplan reading prev','yr3 reading','year 3 reading'],\n  prev_nn:['prev naplan numeracy','previous naplan numeracy','naplan numeracy prev','yr3 numeracy','year 3 numeracy'],\n  prev_patr:['prev pat-r','previous pat-r','pat-r prev','pat-r previous','prev pat reading','prior pat-r'],\n  prev_patm:['prev pat-m','previous pat-m','pat-m prev','pat-m previous','prev pat maths','prior pat-m'],\n  prev_etj:['prev english tj','previous english tj','english tj prev','prev etj','prior english tj'],\n  prev_mtj:['prev maths tj','previous maths tj','maths tj prev','prev mtj','prior maths tj'],\n};\n\nvar mapperCSVLines=[],mapperHeaders=[],mapperFilename='',mapperMode='add';\n\nfunction openMapper(e){\n  var file=e.target.files[0];if(!file)return;\n  mapperFilename=file.name;\n  var reader=new FileReader();\n  reader.onload=function(ev){\n    mapperCSVLines=ev.target.result.split(/\\r?\\n/).filter(function(l){return l.trim();});\n    if(mapperCSVLines.length<2){toast('CSV must have a header row and at least one data row');return;}\n    mapperHeaders=parseCSVRow(mapperCSVLines[0]);\n    e.target.value='';buildMapperUI();\n    document.getElementById('mapper-overlay').classList.add('open');\n  };\n  reader.readAsText(file);\n}\nfunction parseCSVRow(row){\n  var result=[],cur='',inQ=false;\n  for(var i=0;i<row.length;i++){var ch=row[i];if(ch==='\"'){inQ=!inQ;}else if(ch===','&&!inQ){result.push(cur.trim());cur='';}else{cur+=ch;}}\n  result.push(cur.trim());return result;\n}\nfunction autoDetect(key,headers){\n  var kws=KEYWORDS[key]||[];\n  var hl=headers.map(function(h){return h.toLowerCase().replace(/[_\\-]/g,' ').trim();});\n  for(var k=0;k<kws.length;k++){for(var h=0;h<hl.length;h++){if(hl[h]===kws[k]||hl[h].indexOf(kws[k])>-1)return h;}}\n  return -1;\n}\nfunction loadSavedMapping(){try{var s=localStorage.getItem('lnd_mapping2');return s?JSON.parse(s):{};}catch(e){return{};}}\nfunction saveMapping(map){try{localStorage.setItem('lnd_mapping2',JSON.stringify(map));}catch(e){}}\n\nfunction buildMapperUI(){\n  var saved=loadSavedMapping();\n  document.getElementById('mapper-filename').textContent=mapperFilename;\n  var dataRows=mapperCSVLines.length-1;\n  document.getElementById('mapper-source-info').innerHTML='<strong>'+mapperFilename+'</strong> &mdash; '+mapperHeaders.length+' columns, '+dataRows+' data rows.<br><span style=\"color:#94A3B8;font-size:11px;\">Headers: '+mapperHeaders.join(', ')+'</span>';\n  var noOpt='<option value=\"\">\\u2014 not in this file \\u2014</option>';\n  var opts=noOpt+mapperHeaders.map(function(h,i){return'<option value=\"'+i+'\">'+h+'</option>';}).join('');\n  var rows='';var lastSec='';\n  FIELDS.forEach(function(f){\n    if(f.sec&&f.sec!==lastSec){\n      var lbl={lit:'LITERACY \\u2014 CURRENT',num:'NUMERACY \\u2014 CURRENT',prev:'PREVIOUS DATA (for growth)'}[f.sec]||f.sec.toUpperCase();\n      rows+='<tr><td colspan=\"3\" class=\"map-sec '+f.sec+'\">'+lbl+'</td></tr>';\n      lastSec=f.sec;\n    }\n    var detected=-1;var savedH=saved[f.key];\n    if(savedH!==undefined){var idx=mapperHeaders.indexOf(savedH);if(idx>-1)detected=idx;}\n    var isAuto=false;\n    if(detected===-1){detected=autoDetect(f.key,mapperHeaders);isAuto=detected>-1;}\n    rows+='<tr>'+\n      '<td><span style=\"font-size:12px;font-weight:500;color:#0F172A;\">'+f.label+(f.req?'<span style=\"color:#DC2626;margin-left:2px;\">*</span>':'')+'</span>'+\n        '<span style=\"font-size:10px;color:#94A3B8;display:block;margin-top:1px;\">'+f.hint+'</span></td>'+\n      '<td><select id=\"map_'+f.key+'\" class=\"'+(detected>-1?'auto':'')+'\" onchange=\"onMapChange(\\''+f.key+'\\',this);updatePreview()\">'+opts+'</select></td>'+\n      '<td style=\"text-align:center;font-size:13px;\">'+(isAuto?'<span style=\"color:#16A34A;\">\\u2713</span>':detected>-1?'<span style=\"color:#60A5FA;\">\\u21a9</span>':'<span style=\"color:#E2E8F0;\">\\u2014</span>')+'</td>'+\n    '</tr>';\n    if(detected>-1){(function(key,val){setTimeout(function(){var el=document.getElementById('map_'+key);if(el)el.value=val;},0);})(f.key,detected);}\n  });\n  document.getElementById('map-rows').innerHTML=rows;\n  mapperMode='add';\n  document.querySelectorAll('.mode-btn').forEach(function(b){b.classList.remove('active');});\n  document.getElementById('mode-add').classList.add('active');\n  setTimeout(updatePreview,60);\n}\nfunction onMapChange(key,sel){\n  sel.className=sel.value!==''?'auto':'';\n  var sm=loadSavedMapping();\n  if(sel.value!=='')sm[key]=mapperHeaders[parseInt(sel.value)];else delete sm[key];\n  saveMapping(sm);\n}\nfunction setMode(m,btn){mapperMode=m;document.querySelectorAll('.mode-btn').forEach(function(b){b.classList.remove('active');});btn.classList.add('active');}\nfunction getCurrentMapping(){var m={};FIELDS.forEach(function(f){var el=document.getElementById('map_'+f.key);m[f.key]=el&&el.value!==''?parseInt(el.value):-1;});return m;}\n\nfunction parseRow(cols,mapping){\n  function sv(key){var i=mapping[key];return(i>-1&&cols[i]!==undefined)?cols[i].trim():'';}\n  function nv(key){var v=sv(key);return(v===''||isNaN(parseFloat(v)))?null:parseFloat(v);}\n  function iv(key){var v=sv(key);return(v===''||isNaN(parseInt(v)))?null:parseInt(v);}\n  return{name:sv('name'),form:sv('form'),yr:iv('yr')||5,sch:sv('sch'),\n    patr:{a:nv('patr_a'),g:null},nr:{a:nv('nr_a'),g:null},nw:{a:sv('nw_a')||null,g:nv('nw_g')},etj:{a:nv('etj_a'),g:null},\n    patm:{a:nv('patm_a'),g:null},nn:{a:nv('nn_a'),g:null},mtj:{a:nv('mtj_a'),g:null},\n    prev:{patr:nv('prev_patr'),patm:nv('prev_patm'),nr:nv('prev_nr'),nn:nv('prev_nn'),\n      etj:nv('prev_etj'),mtj:nv('prev_mtj'),naplan_yr:iv('naplan_prev_yr'),naplan_testyear:iv('naplan_testyear')}};\n}\nfunction updatePreview(){\n  var mapping=getCurrentMapping();\n  var activeCols=['name','form','yr','sch','patr_a','nr_a','patm_a','prev_patr','prev_nr'];\n  var colLabels={name:'Name',form:'Form',yr:'Year',sch:'School',patr_a:'PAT-R',nr_a:'NAPLAN-R',patm_a:'PAT-M',prev_patr:'Prev PAT-R',prev_nr:'Prev NAPLAN-R'};\n  var shown=activeCols.filter(function(k){return mapping[k]>-1;});\n  if(!shown.length){document.getElementById('preview-table').innerHTML='<tr><td style=\"color:#CBD5E1;font-size:11px;padding:8px;\">Map at least one column to see a preview</td></tr>';return;}\n  var thead='<thead><tr>'+shown.map(function(k){return'<th>'+colLabels[k]+'</th>';}).join('')+'</tr></thead>';\n  var tbody='<tbody>'+mapperCSVLines.slice(1,4).map(function(line){\n    var cols=parseCSVRow(line);var s=parseRow(cols,mapping);\n    return'<tr>'+shown.map(function(k){\n      var v=k==='name'?s.name:k==='form'?s.form:k==='yr'?s.yr:k==='sch'?s.sch:k==='patr_a'?s.patr.a:k==='nr_a'?s.nr.a:k==='patm_a'?s.patm.a:k==='prev_patr'?s.prev.patr:k==='prev_nr'?s.prev.nr:null;\n      return'<td>'+(v!==null&&v!==''?v:'<span style=\"color:#CBD5E1;\">\\u2014</span>')+'</td>';\n    }).join('')+'</tr>';\n  }).join('')+'</tbody>';\n  document.getElementById('preview-table').innerHTML=thead+tbody;\n  var total=mapperCSVLines.length-1;\n  document.getElementById('mapper-count').innerHTML='<strong>'+total+'</strong> student'+(total!==1?'s':'')+' ready to import';\n}\nfunction runImport(){\n  var mapping=getCurrentMapping();\n  if(mapping.name===-1){toast('Please map the Student name column');return;}\n  if(mapperMode==='overwrite'){if(!confirm('Clear all existing data and replace with import?'))return;STUDENTS=[];}\n  var count=0,updated=0;\n  for(var i=1;i<mapperCSVLines.length;i++){\n    var cols=parseCSVRow(mapperCSVLines[i]);var s=parseRow(cols,mapping);if(!s.name)continue;\n    s.id=Date.now()+i;\n    if(mapperMode==='replace'){var ex=STUDENTS.findIndex(function(x){return x.name.toLowerCase()===s.name.toLowerCase();});if(ex>-1){s.id=STUDENTS[ex].id;STUDENTS[ex]=s;updated++;continue;}}\n    STUDENTS.push(s);count++;\n  }\n  persist();closeMapper();initFilters();renderData();\n  var msg=count+' added';if(updated)msg+=', '+updated+' updated';\n  toast(msg+' \\u2014 '+STUDENTS.length+' total');\n}\nfunction closeMapper(){document.getElementById('mapper-overlay').classList.remove('open');mapperCSVLines=[];mapperHeaders=[];}\ndocument.getElementById('mapper-overlay').addEventListener('click',function(e){if(e.target===this)closeMapper();});\n\nfunction downloadTemplate(){\n  var ex='Amelia Chen,5A,5,Riverside PS,118,495,5,115,510,6,3,2023,408,415,109,108,4,5';\n  var blob=new Blob([CSV_HEADER+'\\n'+ex],{type:'text/csv'});\n  var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='student_data_template.csv';a.click();\n}\nfunction exportCSV(){\n  var data=getFiltered();if(!data.length){toast('No data to export');return;}\n  var rows=data.map(function(s){\n    function v(x){return x!==null&&x!==undefined?x:'';}var p=s.prev||{};\n    return[s.name,s.form,s.yr,s.sch,v(s.patr.a),v(s.nr.a),v(s.nw?s.nw.a:null),v(s.etj.a),v(s.patm.a),v(s.nn.a),v(s.mtj.a),v(p.naplan_yr),v(p.naplan_testyear),v(p.nr),v(p.nn),v(p.patr),v(p.patm),v(p.etj),v(p.mtj)].join(',');\n  });\n  var blob=new Blob([CSV_HEADER+'\\n'+rows.join('\\n')],{type:'text/csv'});\n  var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='student_export.csv';a.click();\n}\nfunction clearData(){STUDENTS=[];persist();selId=null;document.getElementById('dpanel').style.display='none';initFilters();renderData();toast('All student data cleared');}\n\n// =====================================================================\n// TAB SWITCHING\n// =====================================================================\nfunction showTab(name,btn){\n  document.querySelectorAll('.tab-panel').forEach(function(p){p.classList.remove('active');});\n  document.querySelectorAll('.tab-btn').forEach(function(b){b.classList.remove('active');});\n  document.getElementById('tab-'+name).classList.add('active');btn.classList.add('active');\n  if(name==='charts')renderCharts();\n  if(name==='growth')renderGrowth();\n}\n\n// =====================================================================\n// TOAST\n// =====================================================================\nvar nasMode=false;\n\nfunction toggleNAS(btn){\n  nasMode=!nasMode;\n  btn.classList.toggle('on',nasMode);\n  btn.style.background=nasMode?'#FF4000':'';\n  btn.style.color=nasMode?'#fff':'';\n  btn.style.borderColor=nasMode?'#FF4000':'';\n  renderData();\n}\nfunction toggleHeatmap(btn){\n  var tbl=document.getElementById('tbl');\n  if(!tbl)tbl=document.querySelector('#tab-data table');\n  if(!tbl)return;\n  var on=tbl.classList.toggle('hm-mode');\n  btn.classList.toggle('on',on);\n  btn.textContent=on?'Show numbers':'Colours only';\n}\nvar toastTimer;\nfunction toast(msg){var el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(function(){el.classList.remove('show');},2500);}\n\n// =====================================================================\n// INIT\n// =====================================================================\ndocument.getElementById('fNm').addEventListener('input',renderData);\nloadSettings();initFilters();renderData();\n</script>\n<div id=\"float-key\" style=\"position:fixed;bottom:18px;right:18px;background:#fff;border:1px solid #E2E8F0;border-radius:10px;padding:8px 12px;box-shadow:0 4px 16px rgba(0,0,0,0.1);z-index:50;font-size:11px;display:flex;flex-direction:column;gap:5px;\">\n  <div style=\"font-size:10px;color:#94A3B8;font-weight:600;letter-spacing:0.04em;margin-bottom:2px;\">COLOUR KEY</div>\n  <div style=\"display:flex;gap:6px;align-items:center;\"><span class=\"rag-exc\" style=\"padding:1px 7px;font-size:11px;\">&#9733;</span> <span style=\"color:#334155;\">Exceeding — above 75th %ile</span></div>\n  <div style=\"display:flex;gap:6px;align-items:center;\"><span class=\"rag-g\" style=\"padding:1px 7px;font-size:11px;\">S</span> <span style=\"color:#334155;\">Strong — 25th–75th %ile</span></div>\n  <div style=\"display:flex;gap:6px;align-items:center;\"><span class=\"rag-a\" style=\"padding:1px 7px;font-size:11px;\">D</span> <span style=\"color:#334155;\">Developing — 5th–25th %ile</span></div>\n  <div style=\"display:flex;gap:6px;align-items:center;\"><span class=\"rag-r\" style=\"padding:1px 7px;font-size:11px;\">!</span> <span style=\"color:#334155;\">NAS — below 5th %ile</span></div>\n  <div style=\"font-size:10px;color:#94A3B8;margin-top:3px;border-top:1px solid #F1F5F9;padding-top:4px;\">Click any row for detail</div>\n</div>\n</body>\n</html>\n";

  var DEBUG = true;
  function log()  { if (DEBUG) console.log.apply(console, ['[LNDashLive]'].concat([].slice.call(arguments))); }
  function warn() { console.warn.apply(console, ['[LNDashLive]'].concat([].slice.call(arguments))); }
  function err()  { console.error.apply(console, ['[LNDashLive]'].concat([].slice.call(arguments))); }

  var MAX_CONCURRENT = 4;
  var queue = [];
  var runningCount = 0;
  function queueTask(fn) {
    return new Promise(function (resolve, reject) {
      queue.push(function (done) {
        fn().then(function (r) { resolve(r); done(); })
            .catch(function (e) { reject(e); done(); });
      });
      runNext();
    });
  }
  function runNext() {
    if (runningCount >= MAX_CONCURRENT || queue.length === 0) return;
    runningCount++;
    var fn = queue.shift();
    fn(function () { runningCount--; runNext(); });
  }
  function withRetry(fn, label, maxAttempts) {
    maxAttempts = maxAttempts || 3;
    var attempt = 0;
    function tryOnce() {
      attempt++;
      return fn().catch(function (e) {
        if (attempt >= maxAttempts) { err(label, 'failed after', attempt, 'attempts'); throw e; }
        var delay = 300 * Math.pow(2, attempt - 1);
        warn(label, 'retry', attempt, 'in', delay, 'ms');
        return new Promise(function (res) { setTimeout(res, delay); }).then(tryOnce);
      });
    }
    return tryOnce();
  }
  function postJson(url, payload) {
    return fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }).then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status + ' on ' + url); return r.json(); });
  }

  var SUBJECT_PATTERNS = {
    english: /^(7|8|9|10)ENG/i,
    maths:   /^(7|8|9|10)(MAT|MAG|MAA|MAF)/i
  };
  function classifySubject(code) {
    if (!code) return null;
    if (SUBJECT_PATTERNS.english.test(code)) return 'english';
    if (SUBJECT_PATTERNS.maths.test(code))   return 'maths';
    return null;
  }

  function classifyValue(raw) {
    if (raw === null || raw === undefined || raw === '') return { status: 'gap', value: null, raw: raw };
    var n = parseFloat(raw);
    if (isNaN(n) || !isFinite(n)) return { status: 'gap', value: null, raw: raw };
    return { status: 'ok', value: n, raw: raw };
  }

  var VC_ITEM_CODES = { VCERV: 'etj', VCEW: 'etjw', VCESL: 'etjsl', VCM2MA: 'mtj' };

  function getReportsStaff(cycleId) {
    return withRetry(function () { return postJson('/Services/Reports.svc/GetReportsStaff', { cycleId: cycleId }); }, 'GetReportsStaff');
  }
  function getOpenCycleActivitiesByUserId(userId, cycleId) {
    return withRetry(function () { return postJson('/Services/Reports.svc/GetOpenCycleActivitiesByUserId', { userId: userId, cycleId: cycleId }); }, 'GetOpenCycleActivitiesByUserId[' + userId + ']');
  }
  function getReportReviewerBlob(entityId, cycleId) {
    return withRetry(function () { return postJson('/Services/Reports.svc/GetReportReviewerBlob', { entityType: 1, entityId: entityId, cycleId: cycleId }); }, 'GetReportReviewerBlob[' + entityId + ']');
  }
  function getEnrolments(activityId) {
    return withRetry(function () { return postJson('/Services/Activity.svc/GetEnrolmentsByActivityId', { activityId: activityId, page: 1, start: 0, limit: 100 }); }, 'GetEnrolmentsByActivityId[' + activityId + ']');
  }
  function getUserResultLines(userIds) {
    return withRetry(function () {
      return postJson('/Services/Reports.svc/GetUserResultLinesByUserIds?sessionstate=readonly&_dc=' + Date.now(),
        { userIds: userIds, includeAllUsers: false, page: 1, start: 0, limit: userIds.length });
    }, 'GetUserResultLinesByUserIds');
  }
  function getCyclesByCycleIds(cycleIds, userIds) {
    return withRetry(function () {
      return postJson('/Services/Cycle.svc/GetCyclesByCycleIds?sessionstate=readonly&_dc=' + Date.now(),
        { cycleIds: cycleIds, userIds: userIds, includeAllUsers: false, page: 1, start: 0, limit: userIds.length });
    }, 'GetCyclesByCycleIds');
  }

  // STEP 1: discover the whole school's classes, walking staff like Reports Check.
  function discoverAllClasses(tjCycleId) {
    return getReportsStaff(tjCycleId).then(function (staffResp) {
      var staffList = (staffResp && staffResp.d) || [];
      log('Found', staffList.length, 'staff reporting in cycle', tjCycleId);

      var classesByActivityId = {};
      var jobs = staffList.map(function (staff) {
        return queueTask(function () {
          return getOpenCycleActivitiesByUserId(staff.userId || staff.id, tjCycleId)
            .then(function (resp) {
              var activities = (resp && resp.d) || [];
              activities.forEach(function (a) {
                classesByActivityId[a.activityId] = {
                  activityId: a.activityId,
                  activityCode: a.activityName || a.name || '',
                  entityId: a.id
                };
              });
            })
            .catch(function (e) { warn('Failed to get activities for staff', staff.userId, e); });
        });
      });

      return Promise.all(jobs).then(function () {
        var classes = Object.values(classesByActivityId);
        log('Discovered', classes.length, 'unique classes school-wide.');
        return classes;
      });
    });
  }

  // STEP 2: for each class, roster + PAT/NAPLAN + TJ.
  function pullEverything(classes, patNaplanCycleIds, tjCycleId, progressCb) {
    var allStudentsById = {};
    var patNaplanResults = {};
    var tjResults = {};
    var failures = [];
    var done = 0;

    var jobs = classes.map(function (cls) {
      return queueTask(function () {
        return getEnrolments(cls.activityId)
          .then(function (enrolResp) {
            var uids = (enrolResp.d || []).map(function (s) { return s.uid; });
            if (!uids.length) return;

            var subPromises = [];

            subPromises.push(
              getUserResultLines(uids).then(function (resp) {
                var rows = (resp.d && resp.d.data) || resp.d || [];
                rows.forEach(function (s) {
                  allStudentsById[s.id] = {
                    id: s.id,
                    name: s.nameFirstLastPref || ((s.firstName || '') + ' ' + (s.lastName || '')),
                    form: s.formGroup,
                    yr: parseInt((s.yearLevelName || '').replace(/\D/g, '')) || null
                  };
                });
              }).catch(function (e) { failures.push({ type: 'roster', activityCode: cls.activityCode, error: e }); })
            );

            if (patNaplanCycleIds.length) {
              subPromises.push(
                getCyclesByCycleIds(patNaplanCycleIds, uids).then(function (resp) {
                  parseCyclesResponse(resp, patNaplanResults);
                }).catch(function (e) { failures.push({ type: 'pat_naplan', activityCode: cls.activityCode, error: e }); })
              );
            }

            if (classifySubject(cls.activityCode)) {
              subPromises.push(
                getReportReviewerBlob(cls.entityId, tjCycleId).then(function (resp) {
                  parseReportBlob(resp, tjResults);
                }).catch(function (e) { failures.push({ type: 'tj', activityCode: cls.activityCode, error: e }); })
              );
            }

            return Promise.all(subPromises);
          })
          .catch(function (e) { failures.push({ type: 'enrolments', activityCode: cls.activityCode, error: e }); })
          .then(function () {
            done++;
            if (progressCb) progressCb(done, classes.length);
          });
      });
    });

    return Promise.all(jobs).then(function () {
      log('Pull complete:', Object.keys(allStudentsById).length, 'students,', failures.length, 'failures.');
      if (failures.length) warn('Failures:', failures);
      return { roster: Object.values(allStudentsById), patNaplanResults: patNaplanResults, tjResults: tjResults, failures: failures };
    });
  }

  // TODO(unverified) #1: response shape (d.cycles[].measures[].cycleMeasureId/name,
  // d.cycles[].enrolments[].userId/results[]) is ASSUMED. Verify against a real
  // GetCyclesByCycleIds response before trusting PAT/NAPLAN values.
  function parseCyclesResponse(response, out) {
    try {
      var cycles = response && response.d && response.d.cycles;
      if (!cycles) { warn('parseCyclesResponse: no d.cycles in response (shape unverified)'); return; }
      cycles.forEach(function (cycle) {
        var measureById = {};
        (cycle.measures || []).forEach(function (m) { measureById[m.cycleMeasureId] = m.name; });
        (cycle.enrolments || []).forEach(function (enrol) {
          var uid = enrol.userId;
          out[uid] = out[uid] || {};
          (enrol.results || []).forEach(function (r) {
            var label = measureById[r.cycleMeasureId] || ('measure_' + r.cycleMeasureId);
            out[uid][label] = classifyValue(r.value);
          });
        });
      });
    } catch (e) { err('parseCyclesResponse threw', e); }
  }

  function parseReportBlob(response, out) {
    try {
      var entities = response && response.d && response.d.entities;
      if (!entities) return;
      entities.forEach(function (entity) {
        var sid = entity.id;
        out[sid] = out[sid] || {};
        (entity.results || []).forEach(function (r) {
          var itemCode = r.itemName || r.name;
          var field = VC_ITEM_CODES[itemCode];
          if (!field) return;
          out[sid][field] = classifyValue(r.value);
        });
      });
    } catch (e) { err('parseReportBlob threw', e); }
  }

  // STEP 3: assemble into index.html's exact STUDENTS shape.
  // TODO(unverified) #2: the PAT/NAPLAN label strings below are PLACEHOLDERS.
  // TODO(unverified) #3: growth (g) and prev{} are always null -- the growth
  //   columns and growth modelling will be empty until a source is wired in.
  // PAT/NAPLAN measure label strings are still PLACEHOLDERS -- fix once a real
  // GetCyclesByCycleIds response with full label names is captured.
  // PAT/NAPLAN measure names are not confirmed yet (TODO #2), so as well as
  // the placeholder name, accept any measure whose name contains the right
  // words. That way whatever Compass actually returns is shown rather than
  // left blank. Prefers a "scale" measure when several match.
  var PAT_MATCH = {
    patr: { exact: 'PAT Reading Scale score', all: [/\bPAT\b/i, /read/i],    none: /NAPLAN/i },
    nr:   { exact: 'NAPLAN Reading',          all: [/NAPLAN/i, /read/i],      none: null },
    nw:   { exact: 'NAPLAN Writing',          all: [/NAPLAN/i, /writ/i],      none: null },
    patm: { exact: 'PAT Maths Scale score',   all: [/\bPAT\b/i, /math/i],    none: /NAPLAN/i },
    nn:   { exact: 'NAPLAN Numeracy',         all: [/NAPLAN/i, /numera/i],    none: null }
  };
  function patValue(obj, field) {
    var m = PAT_MATCH[field];
    if (obj[m.exact] && obj[m.exact].value !== null) return obj[m.exact].value;
    var labels = Object.keys(obj).filter(function (l) {
      return obj[l] && obj[l].value !== null &&
        m.all.every(function (r) { return r.test(l); }) && !(m.none && m.none.test(l));
    }).sort(function (a, b) { return (/scale/i.test(b) ? 1 : 0) - (/scale/i.test(a) ? 1 : 0); });
    return labels.length ? obj[labels[0]].value : null;
  }

  function buildStudentsArray(roster, patNaplanResults, tjResults) {
    return roster.map(function (s) {
      var pat = patNaplanResults[s.id] || {};
      var tj = tjResults[s.id] || {};
      function val(obj, key) { return obj[key] ? obj[key].value : null; }
      return {
        id: s.id, name: s.name, form: s.form, yr: s.yr, sch: 'Crusoe College',
        patr:  { a: patValue(pat, 'patr'), g: null },
        nr:    { a: patValue(pat, 'nr'), g: null },
        nw:    { a: patValue(pat, 'nw'), g: null },
        patm:  { a: patValue(pat, 'patm'), g: null },
        nn:    { a: patValue(pat, 'nn'), g: null },
        etj:   { a: val(tj, 'etj'), g: null },
        etjw:  { a: val(tj, 'etjw'), g: null },
        etjsl: { a: val(tj, 'etjsl'), g: null },
        mtj:   { a: val(tj, 'mtj'), g: null },
        prev:  { patr: null, patm: null, nr: null, nn: null, etj: null, mtj: null, naplan_yr: null, naplan_testyear: null }
      };
    });
  }

  function renderDashboard(studentsArray) {
    var html = DASHBOARD_TEMPLATE;
    if (typeof html !== 'string') { err('Unbuilt userscript -- install dist/lndash-live.user.js (run scripts/build-userscript.sh).'); return; }
    if (!/var\s+STUDENTS\s*=\s*\[\];/.test(html)) { err('Embedded template STUDENTS is not empty -- refusing to render.'); return; }
    // Escape '<' so a value like "</script>" cannot break out of the script tag.
    var json = JSON.stringify(studentsArray).replace(/</g, '\\u003c');
    // Belt and braces: the template also clears this key on load. Clear it
    // here too so an old stale copy can never override the live pull.
    var inject = "try{localStorage.removeItem('lnd_students2');}catch(e){}\n" + 'var STUDENTS = ' + json + ';';
    var replaced = html.replace(/var\s+STUDENTS\s*=\s*\[[\s\S]*?\];/, function () { return inject; });
    if (replaced === html) { err('Layout injection failed -- STUDENTS declaration not found in template.'); return; }
    document.getElementById('lndash-frame').srcdoc = replaced;
    log('Rendered with', studentsArray.length, 'students.');
  }

  // ---------------------------------------------------------------------------
  // UI: overlay with a "Load from Compass" bar. Cycle IDs are remembered in
  // localStorage ('lndash-cycles'); student data never is.
  // ---------------------------------------------------------------------------
  var BTN = 'border:none;border-radius:6px;padding:6px 12px;font-size:12px;cursor:pointer;';
  var INP = 'border:1px solid #CBD5E1;border-radius:6px;padding:5px 8px;font-size:12px;';

  function loadCycleSettings() {
    try { return JSON.parse(localStorage.getItem('lndash-cycles') || '{}'); } catch (e) { return {}; }
  }
  function saveCycleSettings(v) {
    try { localStorage.setItem('lndash-cycles', JSON.stringify(v)); } catch (e) {}
  }
  function readCycleInputs() {
    var tj = document.getElementById('lndash-tj').value.trim();
    var pat = document.getElementById('lndash-pat').value.split(',').map(function (x) { return x.trim(); }).filter(Boolean);
    saveCycleSettings({ tj: tj, pat: pat.join(',') });
    return { tjCycleId: tj, patNaplanCycleIds: pat };
  }

  function buildOverlay() {
    var saved = loadCycleSettings();
    var overlay = document.createElement('div');
    overlay.id = 'lndash-overlay';
    overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;z-index:99999;background:#fff;display:none;flex-direction:column;font-family:system-ui,sans-serif;';
    overlay.innerHTML =
      '<div style="height:44px;background:#0F2847;display:flex;align-items:center;gap:10px;padding:0 14px;flex-shrink:0;">' +
        '<span style="color:#fff;font-weight:600;font-size:13px;">L&amp;N Dashboard — Live from Compass (draft)</span>' +
        '<span id="lndash-status" style="color:#9fb4d0;font-size:12px;"></span>' +
        '<span style="flex:1"></span>' +
        '<button id="lndash-close" style="' + BTN + 'background:#374151;color:#fff;">Close</button>' +
      '</div>' +
      '<div style="display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:10px 14px;background:#F1F5F9;border-bottom:1px solid #E2E8F0;font-size:12px;color:#0F172A;flex-shrink:0;">' +
        '<label>Report cycle <select id="lndash-tj-pick" style="' + INP + 'max-width:200px;"><option value="">Loading cycles...</option></select></label>' +
        '<label>or ID <input id="lndash-tj" style="' + INP + 'width:70px;"></label>' +
        '<label>PAT/NAPLAN cycle IDs <input id="lndash-pat" placeholder="e.g. 101, 102" style="' + INP + 'width:160px;"></label>' +
        '<button id="lndash-load" style="' + BTN + 'background:#1D4ED8;color:#fff;font-weight:600;">Load from Compass</button>' +
        '<button id="lndash-shape" style="' + BTN + 'background:#fff;color:#0F172A;border:1px solid #CBD5E1;">Check data shape</button>' +
        '<span style="color:#64748B;">PAT/NAPLAN cycle IDs: see "Selected Cycles" in a Compass Results Grid.</span>' +
      '</div>' +
      '<div id="lndash-info" style="display:none;padding:10px 14px;border-bottom:1px solid #E2E8F0;font-size:12px;max-height:45vh;overflow:auto;flex-shrink:0;"></div>' +
      '<iframe id="lndash-frame" style="width:100%;flex:1;border:none;"></iframe>';
    document.body.appendChild(overlay);
    document.getElementById('lndash-tj').value = saved.tj || '';
    fillCyclePicker(saved.tj);
    document.getElementById('lndash-pat').value = saved.pat || '';
    document.getElementById('lndash-close').onclick = function () { overlay.style.display = 'none'; };
    document.getElementById('lndash-load').onclick = runFullPull;
    document.getElementById('lndash-shape').onclick = runShapeCheck;
    return overlay;
  }

  // Report cycles come from Reports.svc/GetCycles, the same endpoint Reports
  // Check uses, so nobody has to look up an ID. Most recent cycle first. The
  // ID box stays as a fallback if the list can't be loaded.
  // Most recent cycle first: by start date, then year; Compass's order otherwise.
  function cycleRecency(c) {
    var t = Date.parse(c.start || c.startDate || '');
    if (!isNaN(t)) return t;
    var y = parseInt(c.year, 10);
    return isNaN(y) ? 0 : Date.UTC(y, 0, 1);
  }

  // Loads automatically from the most recent report cycle; the dropdown
  // changes the cycle and reloads.
  var cyclesReady = false, autoLoaded = false;
  function maybeAutoLoad() {
    var overlay = document.getElementById('lndash-overlay');
    if (autoLoaded || !cyclesReady || !overlay || overlay.style.display !== 'flex') return;
    autoLoaded = true;
    runFullPull();
  }

  function fillCyclePicker(savedId) {
    var pick = document.getElementById('lndash-tj-pick');
    var input = document.getElementById('lndash-tj');
    pick.onchange = function () { if (pick.value) { input.value = pick.value; runFullPull(); } };
    postJson('/Services/Reports.svc/GetCycles', { page: 1, start: 0, limit: 25 }).then(function (resp) {
      var cycles = ((resp && resp.d) || []).map(function (c, i) { return { c: c, i: i }; })
        .sort(function (a, b) { return (cycleRecency(b.c) - cycleRecency(a.c)) || (a.i - b.i); })
        .map(function (x) { return x.c; });
      pick.innerHTML = '';
      cycles.forEach(function (c) {
        var o = document.createElement('option');
        o.value = c.id;
        o.textContent = (c.name || ('Cycle ' + c.id)) + (c.year ? ' ' + c.year : '');
        pick.appendChild(o);
      });
      if (!cycles.length) { pick.innerHTML = '<option value="">No cycles found</option>'; return; }
      // Always start from the most recent cycle.
      pick.value = cycles[0].id;
      input.value = pick.value;
      cyclesReady = true;
      maybeAutoLoad();
    }).catch(function (e) {
      warn('GetCycles failed -- type the cycle ID instead', e);
      pick.innerHTML = '<option value="">Could not load -- type ID</option>';
    });
  }

  function setBusy(b) {
    ['lndash-load', 'lndash-shape'].forEach(function (id) {
      var el = document.getElementById(id); if (el) { el.disabled = b; el.style.opacity = b ? 0.5 : 1; }
    });
  }

  // Shows a block of plain text (always via textContent, never innerHTML).
  function showInfo(title, lines, copyText) {
    var box = document.getElementById('lndash-info');
    box.innerHTML = '';
    box.style.display = 'block';
    var h = document.createElement('div');
    h.style.cssText = 'font-weight:600;margin-bottom:6px;display:flex;gap:8px;align-items:center;';
    h.appendChild(document.createTextNode(title));
    var hide = document.createElement('button');
    hide.textContent = 'Hide'; hide.style.cssText = BTN + 'background:#E2E8F0;padding:2px 8px;';
    hide.onclick = function () { box.style.display = 'none'; };
    if (copyText) {
      var copy = document.createElement('button');
      copy.textContent = 'Copy'; copy.style.cssText = BTN + 'background:#1D4ED8;color:#fff;padding:2px 8px;';
      copy.onclick = function () { navigator.clipboard.writeText(copyText).then(function () { copy.textContent = 'Copied'; }); };
      h.appendChild(copy);
    }
    h.appendChild(hide);
    box.appendChild(h);
    lines.forEach(function (l) { var d = document.createElement('div'); d.textContent = l; box.appendChild(d); });
    if (copyText) {
      var pre = document.createElement('pre');
      pre.style.cssText = 'background:#F8FAFC;border:1px solid #E2E8F0;border-radius:6px;padding:8px;white-space:pre-wrap;font-size:11px;margin-top:6px;';
      pre.textContent = copyText;
      box.appendChild(pre);
    }
  }

  function buildLauncher(overlay) {
    var btn = document.createElement('div');
    btn.id = 'lndash-launcher';
    btn.textContent = 'L&N';
    btn.style.cssText = 'position:fixed;width:52px;height:52px;border-radius:50%;background:#0F2847;color:#fff;' +
      'display:flex;align-items:center;justify-content:center;font-weight:600;font-size:12px;cursor:grab;' +
      'z-index:99998;box-shadow:0 2px 8px rgba(0,0,0,0.3);user-select:none;';
    var pos = JSON.parse(localStorage.getItem('lndash-pos') || '{"top":100,"left":20}');
    btn.style.top = pos.top + 'px';
    btn.style.left = pos.left + 'px';
    document.body.appendChild(btn);

    var dragging = false, moved = false, offsetX, offsetY;
    btn.addEventListener('mousedown', function (e) {
      dragging = true; moved = false;
      offsetX = e.clientX - btn.offsetLeft; offsetY = e.clientY - btn.offsetTop;
    });
    document.addEventListener('mousemove', function (e) {
      if (!dragging) return;
      moved = true;
      btn.style.left = (e.clientX - offsetX) + 'px';
      btn.style.top = (e.clientY - offsetY) + 'px';
    });
    document.addEventListener('mouseup', function () {
      if (dragging && moved) localStorage.setItem('lndash-pos', JSON.stringify({ top: parseInt(btn.style.top), left: parseInt(btn.style.left) }));
      dragging = false;
    });
    btn.addEventListener('click', function () {
      if (moved) return;
      overlay.style.display = 'flex';
      maybeAutoLoad();
    });
  }

  function setStatus(text) {
    var el = document.getElementById('lndash-status');
    if (el) el.textContent = text;
  }

  // TODO(unverified) #4: no endpoint found yet that lists PAT/NAPLAN cycles, so
  // cycle IDs are typed into the overlay bar (remembered between runs).
  var pulling = false;
  function runFullPull() {
    if (pulling) return;
    var c = readCycleInputs();
    if (!c.tjCycleId) { setStatus('Enter the report cycle ID first.'); return; }
    if (!c.patNaplanCycleIds.length) warn('No PAT/NAPLAN cycle IDs entered -- those columns will be empty.');

    pulling = true;
    setBusy(true);
    setStatus('Discovering classes...');
    discoverAllClasses(c.tjCycleId).then(function (classes) {
      setStatus('0 / ' + classes.length + ' classes');
      return pullEverything(classes, c.patNaplanCycleIds, c.tjCycleId, function (done, total) {
        setStatus(done + ' / ' + total + ' classes');
      });
    }).then(function (result) {
      setStatus('Rendering...');
      var studentsArray = buildStudentsArray(result.roster, result.patNaplanResults, result.tjResults);
      renderDashboard(studentsArray);
      setStatus(studentsArray.length + ' students loaded' + (result.failures.length ? ' (' + result.failures.length + ' class errors -- see console)' : ''));
      showInfo('What loaded from Compass', loadSummary(studentsArray, result));
    }).catch(function (e) {
      err('Full pull failed:', e);
      setStatus('Error -- see console');
    }).then(function () { pulling = false; setBusy(false); });
  }

  // Counts only -- no names or values -- so staff can see which sources worked.
  function loadSummary(studentsArray, result) {
    function count(field) { return studentsArray.filter(function (s) { return s[field] && s[field].a !== null; }).length; }
    var labels = {};
    Object.keys(result.patNaplanResults).forEach(function (uid) {
      Object.keys(result.patNaplanResults[uid]).forEach(function (l) { labels[l] = true; });
    });
    var lines = [
      'Students: ' + studentsArray.length,
      'Teacher judgements -- Reading ' + count('etj') + ', Writing ' + count('etjw') + ', Speaking ' + count('etjsl') + ', Maths ' + count('mtj'),
      'PAT/NAPLAN -- PAT-R ' + count('patr') + ', PAT Maths ' + count('patm') + ', NAPLAN Reading ' + count('nr') + ', Writing ' + count('nw') + ', Numeracy ' + count('nn'),
      'Class errors: ' + result.failures.length + (result.failures.length ? ' (see console)' : '')
    ];
    var found = Object.keys(labels);
    if (found.length) {
      lines.push('PAT/NAPLAN measure names Compass returned (' + found.length + '): ' + found.join(' | '));
      lines.push('If PAT/NAPLAN counts are 0 but names appear above, the names in buildStudentsArray() need updating to match (TODO #2).');
    } else if (result.patNaplanResults && Object.keys(result.patNaplanResults).length === 0) {
      lines.push('No PAT/NAPLAN results parsed. Use "Check data shape" and send the output (TODO #1).');
    }
    return lines;
  }

  // ---------------------------------------------------------------------------
  // "Check data shape": samples ONE class and reports the STRUCTURE of the
  // Compass responses (field names and types) plus measure/item labels. Every
  // other value is replaced with its type, and any label that matches a string
  // from the class roster is dropped, so the output contains no student data.
  // Staff should still read it before sharing.
  // ---------------------------------------------------------------------------
  var LABEL_KEYS = /^(name|label|title|description|code|shortName|itemName|measureName|displayName|columnName|cycleName|type|typeName)$/i;
  var LABEL_PATH = /measure|item|column|cycle|template|component/i;
  var PERSON_PATH = /user|student|enrol|person|staff|entit|learner|parent|teacher/i;

  function isLabelPath(path, key) { return LABEL_KEYS.test(key) && LABEL_PATH.test(path) && !PERSON_PATH.test(path); }

  function shapeOf(v, path, key, blocked) {
    if (v === null || v === undefined) return null;
    if (Array.isArray(v)) {
      if (!v.length) return [];
      return [shapeOf(v[0], path + '[]', key, blocked), '... ' + v.length + ' item(s)'];
    }
    if (typeof v === 'object') {
      var o = {};
      Object.keys(v).forEach(function (k) { o[k] = shapeOf(v[k], path + '.' + k, k, blocked); });
      return o;
    }
    if (typeof v === 'string' && isLabelPath(path, key) && !isBlocked(v, blocked)) return 'label: ' + v.slice(0, 80);
    return typeof v;
  }

  function collectLabels(v, path, key, blocked, out) {
    if (v === null || v === undefined) return;
    if (Array.isArray(v)) { v.forEach(function (x) { collectLabels(x, path + '[]', key, blocked, out); }); return; }
    if (typeof v === 'object') { Object.keys(v).forEach(function (k) { collectLabels(v[k], path + '.' + k, k, blocked, out); }); return; }
    if (typeof v === 'string' && isLabelPath(path, key) && !isBlocked(v, blocked)) out[path + ' = ' + v.slice(0, 80)] = true;
  }

  function collectStrings(v, out) {
    if (v === null || v === undefined) return;
    if (Array.isArray(v)) { v.forEach(function (x) { collectStrings(x, out); }); return; }
    if (typeof v === 'object') { Object.keys(v).forEach(function (k) { collectStrings(v[k], out); }); return; }
    if (typeof v === 'string') v.split(/[\s,]+/).forEach(function (w) { if (w.length >= 3) out[w.toLowerCase()] = true; });
  }
  function isBlocked(str, blocked) {
    return str.split(/[\s,]+/).some(function (w) { return w.length >= 3 && blocked[w.toLowerCase()]; });
  }

  function runShapeCheck() {
    var c = readCycleInputs();
    if (!c.tjCycleId) { setStatus('Enter the report cycle ID first.'); return; }
    setBusy(true);
    setStatus('Checking data shape (one class)...');
    var report = { note: 'Structure only. Values replaced by their type; roster strings removed.', tjCycleId: c.tjCycleId, patNaplanCycleIds: c.patNaplanCycleIds };
    var blocked = {};

    getReportsStaff(c.tjCycleId).then(function (staffResp) {
      var staff = (staffResp && staffResp.d) || [];
      report.GetReportsStaff = shapeOf(staffResp, 'staffResp', '', {});
      // Find the first staff member with an English or Maths class.
      var k = 0;
      function next() {
        if (k >= staff.length || k >= 25) return Promise.resolve(null);
        var st = staff[k++];
        return getOpenCycleActivitiesByUserId(st.userId || st.id, c.tjCycleId).then(function (resp) {
          var acts = (resp && resp.d) || [];
          var hit = acts.filter(function (a) { return classifySubject(a.activityName || a.name || ''); })[0];
          if (hit) { report.GetOpenCycleActivitiesByUserId = shapeOf(resp, 'activities', '', {}); return hit; }
          return next();
        });
      }
      return next();
    }).then(function (a) {
      if (!a) throw new Error('No English/Maths class found in the first 25 staff for this cycle.');
      return getEnrolments(a.activityId).then(function (enrol) {
        collectStrings(enrol, blocked);
        report.GetEnrolmentsByActivityId = shapeOf(enrol, 'enrolments', '', blocked);
        var uids = (enrol.d || []).map(function (s) { return s.uid; }).slice(0, 5);
        var jobs = [
          getReportReviewerBlob(a.id, c.tjCycleId).then(function (r) {
            collectStrings(((r && r.d && r.d.entities) || []).map(function (e) { return e.name || e.displayName || ''; }), blocked);
            report.GetReportReviewerBlob = shapeOf(r, 'blob', '', blocked);
          }).catch(function (e) { report.GetReportReviewerBlob = 'ERROR: ' + e.message; })
        ];
        if (c.patNaplanCycleIds.length && uids.length) {
          jobs.push(getCyclesByCycleIds(c.patNaplanCycleIds, uids).then(function (r) {
            var labels = {};
            collectLabels(r, 'cyclesResp', '', blocked, labels);
            report.GetCyclesByCycleIds = shapeOf(r, 'cyclesResp', '', blocked);
            report.GetCyclesByCycleIds_allLabels = Object.keys(labels);
          }).catch(function (e) { report.GetCyclesByCycleIds = 'ERROR: ' + e.message; }));
        } else {
          report.GetCyclesByCycleIds = 'skipped -- enter PAT/NAPLAN cycle IDs to include it';
        }
        return Promise.all(jobs);
      });
    }).then(function () {
      setStatus('Data shape ready');
      showInfo('Compass data shape (no student data -- please read it before sharing)', [
        'Field names and types only. Labels shown are measure/item names, not results.',
        'Copy this and send it to whoever is finishing the PAT/NAPLAN parsing.'
      ], JSON.stringify(report, null, 2));
    }).catch(function (e) {
      err('Shape check failed:', e);
      setStatus('Shape check failed -- see console');
    }).then(function () { setBusy(false); });
  }

  var overlay = buildOverlay();
  if (FROM_LAUNCHER) { overlay.style.display = 'flex'; maybeAutoLoad(); }
  else buildLauncher(overlay);
  log('Launcher ready.');

})();
